const top_kled = {
  champion: '클레드',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌은 (Q)\'결정타\'로 이동 속도를 올려 빠르게 다가와 침묵을 걸려고 해요. 거리를 재다가 가렌이 (Q)\'결정타\'를 쓴 뒤 빈틈이 생기면 (Q)\'덫날리기\'를 맞춰 짧게 교환하세요. 무리하게 붙어 싸우기보다 짧게 평타를 넣고 빠지는 것이 좋아요.', lv3: '가렌이 (Q)\'결정타\'를 사용해 침묵을 걸면 스킬 사용이 불가능하니, 침묵이 풀리는 순간 (E)\'이랴!\'로 진입해 (W)\'버럭버럭\' 평타를 빠르게 넣으세요. (W)\'용기\' 보호막이 켜져 있을 때는 피해량이 줄어드니, 보호막이 사라진 뒤 (Q)\'덫날리기\'로 끌어당겨 피해를 집중하는 것이 효율적이에요. (E)\'심판\'의 회전 피해를 다 맞으면 방어력이 깎이니, 가렌의 회전이 끝나기 전에 거리를 벌리거나 빠르게 승부를 보세요.', lv6: '가렌의 체력이 낮을 때 (R)\'돌겨어어억!!!\'으로 진입해 킬각을 잡으세요. 내 체력이 낮으면 (R)\'데마시아의 정의\'의 고정 피해에 순식간에 처치될 수 있으니 무리하게 붙지 마세요. 가렌은 (Q)\'결정타\'로 둔화를 풀고 이동 속도를 올려 빠져나갈 수 있으니, (Q)\'결정타\'가 빠진 뒤 정글러와 함께 (E)\'이랴!\'로 접근해 협공하세요.', item: '삼위일체를 첫 코어로 선택해 공격력과 체력을 보충하고, 스킬을 쓴 뒤 다음 기본 공격 피해를 높이세요. 신발은 가렌의 기본 공격 피해를 줄여 주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 가렌의 (P)\'인내심\' 회복을 억제하면 체력 유지력을 낮추고 마무리하기 쉬워요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 견제하며 골드를 챙기니 거리 조절을 잘 해야 해요. 근접할 때는 (Q)\'덫날리기\'를 맞춰서 끌어당긴 뒤 (W)\'버럭버럭\'의 빠른 평타를 섞어 교환하세요. (P)\'불의 심판\'은 몇 초에 한 번씩 근접 공격에 불을 붙이니 붙어서 길게 평타를 주고받지 말고 짧게 교전하고 빠지세요.', lv3: '갱플랭크가 (W)\'괴혈병 치료\'로 체력을 회복하고 군중 제어를 풀 수 있으니 이 스킬을 먼저 쓰게 유도하세요. (E)\'화약통\' 근처에서 싸우면 폭발 피해와 둔화가 발생하니 통이 없는 위치를 잡는 것이 중요해요. (E)\'이랴!\'로 진입한 뒤 (Q)\'덫날리기\'를 적중시켜 끌어당기며 몰아치면 효과적이에요.', lv6: '(R)\'돌겨어어억!!!\'로 보호막을 두르고 진입해 스칼의 공격으로 피해를 입히며 압박하세요. 갱플랭크가 (R)\'포탄 세례\'를 사용하면 둔화로 인해 추격이 어려우니 장판 밖에서 움직이는 것이 좋아요. (W)\'괴혈병 치료\'가 빠진 타이밍에 (E)\'이랴!\'와 함께 몰아치면 킬을 따내기 훨씬 수월해요.', item: '첫 코어 아이템으로 갈라진 하늘을 올려 전투 지속력을 높여주세요. 신발은 갱플랭크의 근접 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'괴혈병 치료\'의 체력 회복 효과를 줄여야 갱플랭크를 확실히 처치할 수 있어요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸고 (P)\'서비스 시간\'으로 체력을 회복하며 견제해요. 술통이 빗나간 틈에 (E)\'이랴!\'로 진입해 짧게 딜교환하며 스칼의 용기를 쌓으세요. 억지로 붙으려다 둔화에 걸리면 스칼의 체력만 깎이니 거리 조절에 신경 쓰세요.', lv3: '그라가스의 (E)\'몸통 박치기\' 기절에 맞으면 진입 흐름이 끊기니 이 스킬이 빠진 것을 확인하고 들어가세요. (Q)\'덫날리기\'로 상대를 붙잡은 뒤 (W)\'버럭버럭\'으로 빠르게 네 번의 공격을 몰아쳐 체력을 깎으세요. 상대가 (W)\'취중 분노\'를 켜서 피해를 줄일 때는 잠시 물러났다가 효과가 끝난 뒤에 다시 공격하세요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 믿고 과감하게 진입하되 그라가스의 (R)\'술통 폭발\'에 밀려나 딜교환이 끊기지 않게 주의하세요. 밀려난 후에도 (E)\'이랴!\'로 빠르게 다시 붙어 킬각을 잡는 것이 중요해요. 라인을 밀어두면 그라가스가 아군 정글러와 연계해 나를 밀어낼 위험이 있으니 시야를 확보하세요.', item: '삼위일체를 가서 공격 속도와 체력을 챙기고 강력한 평타 피해를 입히세요. 신발은 그라가스의 마법 피해를 줄이고 (Q)\'술통 굴리기\' 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'으로 인한 그라가스의 체력 회복을 억제하고 확실하게 처치하기 위해서예요.' },
    '그웬': { lv1: '1~2레벨에는 그웬의 (Q)\'싹둑싹둑!\' 범위 안으로 무리하게 들어가지 말고 거리를 조절하며 (Q)\'덫날리기\'로 먼저 견제하세요. 스칼의 용기를 잃지 않도록 짧은 딜교환 위주로 하며 미니언을 챙기는 데 집중하세요. 그웬이 기본 공격으로 (Q)\'싹둑싹둑!\' 가위질 중첩을 쌓기 전에 거리를 벌리는 게 중요해요.', lv3: '그웬이 (W)\'신성한 안개\'를 켜면 안개는 대상 지정만 막으니, 대상 지정이 아닌 (Q)\'덫날리기\'는 그대로 맞힐 수 있어요. 그웬의 (E)\'돌격가위\'가 빠진 타이밍에 (E)\'이랴!\'로 접근해 (W)\'버럭버럭\'으로 짧게 딜교환을 시도하세요. 안개 안에서는 그웬의 방어력과 마법 저항력이 올라가니 안개가 걷힌 뒤에 몰아치는 것이 좋아요.', lv6: '그웬이 (R)\'바느질\'로 둔화를 걸며 거리를 벌리려 하면 (R)\'돌겨어어억!!!\'의 보호막을 두르고 돌진해 맞서세요. (R)\'바느질\'은 재사용할 때마다 피해가 커지니 체력이 낮을 때는 무리하지 마세요. 스칼에서 내렸다면 싸움을 이어가며 용기를 채워 다시 탑승하는 것에 집중하세요.', item: '첫 코어로 갈라진 하늘을 선택하고 신발은 헤르메스의 발걸음을 가주세요. 갈라진 하늘은 체력과 공격력을 제공하며 헤르메스의 발걸음은 마법 저항력을 제공해요.', spell: '점멸과 점화를 추천해요. 점화로 그웬의 (P)\'가위 난도질\' 회복량을 줄여야 킬을 따내기 쉬워요.' },
    '나르': { lv1: '나르가 (Q)\'부메랑 던지기\'로 멀리서 둔화를 걸며 견제하니 부메랑이 돌아오는 타이밍을 피해 미니언 사이에서 파밍하세요. 2레벨에 (E)\'이랴!\'를 배우면 빠르게 접근해서 (Q)\'덫날리기\'로 적을 끌어당기며 스칼의 용기를 채우는 싸움을 시도해요. 초반에는 나르의 둔화에 걸려 무리하게 쫓기지 않도록 거리 조절에 신경 써야 해요.', lv3: '나르가 (E)\'폴짝\'으로 거리를 벌리려 하면 (E)\'이랴!\'를 사용하여 빠르게 따라붙으며 (W)\'버럭버럭\'의 공격 속도로 몰아붙이세요. 나르의 분노가 쌓여 메가 나르가 되면 (W)\'쿵쾅\'에 기절할 수 있으니 변신 직전에는 거리를 두는 것이 좋아요. 작은 나르일 때 (Q)\'덫날리기\'를 적중시켜 끌어당기고 빠르게 근접해서 딜교환을 마무리하세요.', lv6: '메가 나르가 (R)\'나르!\'로 적을 던져 벽에 부딪히게 하면 기절하므로 벽 근처에서는 싸움을 피하세요. (R)\'돌겨어어억!!!\'로 보호막을 얻으며 진입할 때 나르의 궁극기 범위에 들어가지 않도록 위치를 잡아야 해요. 메가 나르의 변신이 풀려 작은 나르가 되었을 때 (Q)\'덫날리기\'를 맞춰 빠르게 몰아치면 킬을 따내기 편해요.', item: '삼위일체로 전투 지속력을 높이고 공격력을 확보하세요. 신발은 나르의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 나르의 체력을 깎아 마무리 피해를 입히고 점멸로 나르의 스킬을 피하며 진입하세요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\'으로 미니언을 먹으며 성장하려 하니 1~2레벨에 적극적으로 압박하세요. 나서스가 (Q)\'흡수의 일격\'을 쓰려고 다가올 때 (Q)\'덫날리기\'로 맞받아 짧게 교환하세요. (E)\'이랴!\'로 빠르게 진입해 짧은 딜교환을 반복하는 것이 좋아요.', lv3: '나서스의 (W)\'쇠약\'에 걸리면 이동 속도와 공격 속도가 줄어드니 주의하며 거리를 유지하세요. (E)\'영혼의 불길\'이 깔린 지역에서는 방어력이 낮아지므로 그 위에서의 싸움은 피하세요. (E)\'이랴!\'로 진입한 뒤 (Q)\'덫날리기\'를 맞춰 적을 끌어당기며 (W)\'버럭버럭\'의 빠른 평타로 싸우세요.', lv6: '나서스가 (R)\'사막의 분노\'를 쓰면 체력과 공격 범위가 늘어나니 폭풍 속에서의 교전은 피하세요. (R)\'돌겨어어억!!!\'의 보호막을 이용해 킬을 노리거나 위험할 때 탈출하는 용도로 사용하세요. 라인을 강하게 밀어 넣어 나서스가 (Q)\'흡수의 일격\' 스택을 쌓을 시간을 줄이세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 전투 능력을 높이고 판금 장화로 나서스의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'영혼의 포식자\'의 생명력 흡수를 억제하며 초반에 압박하세요.' },
    '녹턴': { lv1: '(Q)\'황혼의 인도자\' 투사체를 피해서 녹턴이 이동 속도와 공격력을 얻지 못하게 하세요. (Q)\'덫날리기\'를 사용하여 접근하는 녹턴을 붙잡으며 딜교환을 유도하고 미니언을 챙기세요.', lv3: '녹턴의 (W)\'어둠의 장막\'은 짧게 유지되며 다음 스킬 하나를 막는 방어막이니, 켜진 동안에는 (Q)\'덫날리기\'를 아끼고 끝난 뒤에 사용하세요. (E)\'이랴!\'로 빠르게 접근해 (W)\'버럭버럭\'의 공격 속도로 압박하고 (E)\'말할 수 없는 공포\'의 사거리 밖으로 벗어나 공포를 피하세요.', lv6: '녹턴이 (R)\'피해망상\'으로 진입할 때 (R)\'돌겨어어억!!!\'의 보호막을 활용해 피해를 흡수하고 적을 밀어내세요. 시야가 차단된 동안 정글 개입에 주의하며 (E)\'이랴!\'와 (Q)\'덫날리기\'를 연계해 킬각을 잡으세요.', item: '판금 장화와 삼위일체를 선택해요. 판금 장화로 (P)\'그림자 칼날\'의 기본 공격 피해를 줄이고 삼위일체의 공격력과 체력으로 지속 전투력을 높이기 위해서예요.', spell: '점멸과 점화를 선택해요. (P)\'그림자 칼날\'의 체력 회복 효과를 억제하고 확실하게 적을 처치하기 위해서예요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩이 쌓일수록 강해지니 1~2레벨에 길게 붙어 싸우지 마세요. (Q)\'덫날리기\'로 먼저 견제하며 거리를 조절하고, 다리우스가 (Q)\'학살\'의 도끼날을 휘두르기 전에 적절한 거리를 유지하며 스칼의 용기를 관리하세요.', lv3: '다리우스가 (E)\'포획\'을 사용해 끌어당기면 매우 위험하니 그 사거리 안에서 머물지 마세요. 다리우스의 (E)\'포획\'이 빠진 것을 확인했다면 (E)\'이랴!\'로 빠르게 진입하여 (W)\'버럭버럭\'의 공격 속도 증가 효과를 이용해 짧게 딜교환을 하고 빠지세요.', lv6: '다리우스의 (R)\'녹서스의 단두대\'는 (P)\'과다출혈\' 중첩이 높을 때 치명적이니 체력이 낮을 때 무리한 싸움은 피하세요. (R)\'돌겨어어억!!!\'을 사용해 보호막을 얻으며 진입하고, 스칼을 다시 태우기 위해 전투를 지속하며 라인을 관리하세요.', item: '판금 장화와 발걸음 분쇄기를 선택하세요. 판금 장화는 다리우스의 기본 공격 피해를 줄여주고, 발걸음 분쇄기는 공격력과 체력을 제공해요.', spell: '점멸과 점화를 추천해요. (E)\'포획\'에 끌려오기 전에 점멸로 거리를 조절하고, 점화로 (Q)\'학살\'의 회복을 줄이며 마무리하세요.' },
    '라이즈': { lv1: '라이즈가 (Q)\'과부하\'로 멀리서 견제하기 때문에 미니언 사이에 섞여서 피해를 최소화하세요. 1~2레벨에는 (E)\'이랴!\'를 사용하여 적에게 접근하며 짧은 딜교환을 시도하고 스칼의 용기를 관리하세요. 라이즈의 마나가 부족해지는 시점을 노려 압박하세요.', lv3: '라이즈가 (E)\'주문 전이\'로 표식을 남긴 뒤 (W)\'룬 감옥\'을 쓰면 속박이 걸리니 주의하세요. (W)\'룬 감옥\'이 빠진 타이밍에 (E)\'이랴!\'로 돌진하여 (Q)\'덫날리기\'로 적을 끌어당기면 딜교환을 성공적으로 할 수 있어요. (W)\'버럭버럭\'을 활용해 빠르게 평타를 섞어주세요.', lv6: '라이즈가 (R)\'공간 왜곡\'으로 차원문을 열면 잠시 뒤 순간이동으로 빠져나가니, 무리하게 쫓기보다 이동 전에 최대한 피해를 넣으세요. (R)\'돌겨어어억!!!\'의 보호막을 활용해 라이즈의 스킬 피해를 버티며 싸우는 것이 중요해요. 라이즈의 체력이 낮을 때 정글러를 호출하여 확실하게 킬을 노려보세요.', item: '삼위일체를 첫 코어로 올려 공격력과 체력을 동시에 챙기세요. 신발은 마법 저항력을 제공하는 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 라이즈가 거리를 벌리기 전에 점멸로 접근하여 점화로 확실하게 마무리하세요.' },
    '럼블': { lv1: '럼블의 (E)\'전기 작살\'은 (Q)\'덫날리기\'보다 사거리가 길기 때문에 원거리에서 들어오는 견제를 조심해야 해요. (Q)\'화염방사기\'의 범위에 들어가지 않도록 거리 조절을 하세요. 스칼의 용기를 잃지 않도록 무리한 교환은 피하세요.', lv3: '럼블의 (W)\'고철 방패\'가 켜져 있을 때는 (E)\'이랴!\'로 진입해도 피해를 막아내니 방패가 사라진 뒤를 노리세요. (E)\'전기 작살\'을 피한 뒤 (Q)\'덫날리기\'로 럼블을 붙잡고 (W)\'버럭버럭\'을 활용해 짧고 강하게 교환해요. 럼블의 열기가 높아져 위험 상태가 되면 교환을 피하고 거리를 두세요.', lv6: '럼블이 (R)\'이퀄라이저 미사일\'을 사용하면 불타는 궤적 위에서 싸우지 말고 즉시 벗어나세요. 럼블의 스킬이 빠진 타이밍에 (R)\'돌겨어어억!!!\'으로 진입해 보호막을 얻으며 압박하세요. 럼블의 궁극기는 정글러의 개입과 잘 어울리니 라인 관리 시 주의하세요.', item: '첫 코어로 갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 럼블의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 점멸로 럼블과의 거리를 단숨에 좁혀 (Q)\'덫날리기\'를 맞히고, 점화로 마무리 피해를 더해 킬각을 확실하게 잡으세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'을 사용해 체력을 회복하며 초반 교전에서 강한 모습을 보여요. 1~2레벨에는 레넥톤의 분노가 쌓이지 않도록 거리를 조절하며 (Q)\'덫날리기\'로 짧게 견제하세요. 레넥톤이 (Q)\'양떼 도륙\'으로 체력을 회복하는 타이밍에는 무리하게 맞붙지 말고 거리를 두는 것이 좋아요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 진입할 때 (Q)\'덫날리기\'를 맞혀 멀어지지 못하게 붙잡으세요. 분노가 쌓인 레넥톤의 (W)\'무자비한 포식자\'는 더 오래 기절시키니, 분노가 높을 때는 교전을 미루고 분노를 쓴 뒤에 (E)\'이랴!\'로 진입하세요. (W)\'무자비한 포식자\'가 빠진 틈에 (W)\'버럭버럭\'의 네 번째 공격까지 넣어 딜교환을 마무리하세요.', lv6: '레넥톤이 (R)\'강신\'을 사용해 체력을 얻고 강력해지면 라인을 당겨서 관리하며 정글러의 지원을 기다리세요. (R)\'돌겨어어억!!!\'의 보호막을 활용해 레넥톤의 피해를 흡수하고, 스칼이 적을 밀어낼 때 거리를 조절하세요. 레넥톤의 궁극기 지속시간이 끝난 뒤에 (E)\'이랴!\'와 (Q)\'덫날리기\'로 적극적으로 진입해 킬각을 보세요.', item: '굶주린 히드라를 첫 코어로 선택해 생명력 흡수로 라인 유지력을 높이세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\' 체력 회복 효과를 감소시켜 교전에서 앞서가세요.' },
    '렝가': { lv1: '수풀에서 (P)\'보이지 않는 포식자\'로 도약하는 것을 경계하며 라인을 유지하세요. (Q)\'덫날리기\'로 렝가를 붙잡아 거리를 조절하고 (Q)\'포악함\'의 진입을 억제해야 해요. 스칼의 체력이 낮다면 무리하지 말고 용기를 회복하는 데 집중하세요.', lv3: '최대 야성으로 강화된 (E)\'올가미 투척\'에 맞으면 속박되어 (E)\'이랴!\' 같은 돌진을 쓸 수 없으니 올가미를 피하세요. 올가미가 빠진 타이밍에 (E)\'이랴!\'로 진입해 (W)\'버럭버럭\'으로 딜교환을 시도하세요. 렝가가 야성을 모아 (W)\'전투의 포효\'로 군중 제어를 풀기 전에 빠르게 공격을 마무리하세요.', lv6: '(R)\'사냥의 전율\'로 위장해 도약해 오는 렝가에게 (R)\'돌겨어어억!!!\'의 보호막으로 피해를 버티며 맞서세요. 렝가의 도약은 방어력을 깎으니 체력이 낮을 때는 거리를 두세요. 라인을 당겨 정글러의 개입을 노리며 렝가의 도약 사거리 안에서 오래 버티지 마세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 렝가의 기본 공격 피해를 줄여주고 갈라진 하늘은 체력을 높여 스칼의 생존력을 돕고 첫 타격 시 체력을 회복시켜줘요.', spell: '점멸과 점화. 렝가의 (W)\'전투의 포효\' 회복량을 줄이고 킬각을 잡기 위해 필요해요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 사용해 빠르게 접근하고 (P)\'룬 검\'으로 추가 피해를 입히는 구간이 강해요. 1~2레벨에는 리븐의 진입을 (Q)\'덫날리기\'로 견제하며 스칼의 용기를 잘 보존하는 것이 중요해요. 리븐이 (Q)\'부러진 날개\'로 들어올 때 무리하게 맞붙지 말고 거리를 조절하며 대응하세요.', lv3: '리븐이 (W)\'기 폭발\'로 기절을 시키려 할 때 (E)\'이랴!\'를 사용해 적절히 대응하며 딜교환을 준비하세요. 리븐의 (E)\'용맹\' 보호막이 빠진 것을 확인한 뒤 (W)\'버럭버럭\'과 (E)\'이랴!\'를 사용하여 강하게 몰아치세요. (Q)\'부러진 날개\' 세 번째 타격으로 공중으로 뜨는 것을 조심하며 내 스킬을 적중시키세요.', lv6: '리븐이 (R)\'추방자의 검\'을 켜면 사거리가 길어지니 체력이 낮을 때는 거리를 두며 라인을 관리하세요. (R)\'돌겨어어억!!!\'의 보호막으로 리븐의 공격을 버티며 진입해 연계를 끊으세요. 리븐의 주요 스킬이 빠졌을 때 정글러와 함께 싸우세요.', item: '판금 장화와 삼위일체를 추천해요. 판금 장화는 방어력을 높여주고 삼위일체는 공격력과 체력을 제공해 전투를 돕기 때문이에요.', spell: '점멸과 점화를 추천해요. 리븐의 (E)\'용맹\' 보호막이 사라진 타이밍에 점화를 사용해 킬을 가져오세요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'을 던져 둔화를 걸며 견제하는데, 첫 적중 대상 뒤로 파편이 튀므로 미니언과 겹쳐 서지 마세요. 1~2레벨에는 (E)\'이랴!\'로 빠르게 접근해 짧게 평타를 섞으며 스칼의 용기를 회복하는 것이 중요해요. 상대의 스킬 쿨타임을 확인하며 적절한 거리를 유지하세요.', lv3: '(W)\'서릿발\'에 속박되면 (E)\'이랴!\' 같은 돌진기를 쓸 수 없으니, 리산드라가 (W)\'서릿발\'을 먼저 쓰게 유도한 뒤 진입하세요. (E)\'얼음갈퀴 길\'로 도망치기 전에 (Q)\'덫날리기\'를 맞춰 끌어당겨야 딜교환을 이어갈 수 있어요. (W)\'버럭버럭\'의 빠른 공격으로 강한 피해를 입히고 빠르게 빠지는 패턴을 반복하세요.', lv6: '(R)\'얼음 무덤\'의 기절을 맞기 전에 (R)\'돌겨어어억!!!\'의 보호막으로 진입해 피해를 흡수하며 붙으세요. 리산드라가 자신에게 (R)\'얼음 무덤\'을 써서 무적 상태가 되면 딜을 멈추고 경직이 끝날 때까지 기다리세요. 라인을 밀어 넣은 상태에서 정글러와 함께 진입하면 (W)\'서릿발\'과 (R)\'얼음 무덤\'이 빠진 틈을 노리기 쉬워요.', item: '맬모셔스의 아귀를 첫 코어로 선택해 마법 저항력을 높이고 생명선 보호막으로 생존력을 챙기세요. 신발은 (W)\'서릿발\'의 속박과 (R)\'얼음 무덤\'의 기절 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. (R)\'얼음 무덤\'의 기절이나 (W)\'서릿발\'의 속박을 정화로 빠르게 풀고 곧바로 반격할 수 있어요.' },
    '마스터이': { lv1: '마스터 이는 (P)\'2연속 공격\'으로 빠르게 공격하며 (E)\'우주류 검술\'의 고정 피해가 들어와 평타 교환이 강해요. 1~2레벨에는 무리하게 붙지 말고 (Q)\'덫날리기\'로 적당한 거리를 유지하며 견제하세요. 스칼의 체력이 낮아지면 빠르게 빠져서 용기를 회복해야 해요.', lv3: '(Q)\'일격 필살\'을 사용한 마스터 이는 잠시 대상으로 지정할 수 없으니 이 스킬이 빠진 것을 확인하고 (E)\'이랴!\'로 진입하세요. 마스터 이가 (W)\'명상\'으로 피해를 줄이며 체력을 회복할 때는 (W)\'버럭버럭\'의 빠른 공격을 아꼈다가 명상이 끝난 뒤에 쏟아내세요. (E)\'이랴!\'는 돌진 경로의 미니언을 앞으로 끌어당기니 진입 각도를 잘 잡으세요.', lv6: '(R)\'최후의 전사\'를 켠 마스터 이는 둔화에 면역이라 (Q)\'덫날리기\'의 둔화 효과는 통하지 않지만 끌어당기기는 가능해요. (R)\'돌겨어어억!!!\'의 보호막으로 상대의 폭딜을 버티며 진입하고 적을 뒤로 밀어내어 거리 조절을 하세요. 마스터 이가 처치 관여로 스킬 재사용 대기시간을 줄이지 못하도록 정글 개입 상황에서 아군 체력을 관리하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기세요. 신발은 판금 장화로 기본 공격 피해를 줄이되, 방어력으로는 (E)\'우주류 검술\'의 고정 피해를 막지 못하니 교환은 짧게 가져가세요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복하는 것을 점화로 억제해야 확실하게 마무리할 수 있어요.' },
    '마오카이': { lv1: '마오카이는 (Q)\'덤불 주먹\'으로 적을 밀쳐내며 둔화를 걸고 (P)\'마법 흡수\'로 체력을 회복해요. 1~2레벨에는 마오카이가 스킬을 사용해 (P)\'마법 흡수\'로 체력을 회복할 타이밍을 피해 (Q)\'덫날리기\'로 빠르게 끌어당겨 딜교환을 하세요. (Q)\'덤불 주먹\'의 충격파 사거리 밖에서 거리를 조절하며 대응해요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'을 사용하면 대상으로 지정할 수 없으므로, 이 스킬이 빠진 것을 확인한 뒤 (E)\'이랴!\'로 돌진하세요. (W)\'뒤틀린 전진\'의 속박을 맞지 않도록 주의하며 (Q)\'덫날리기\'로 마오카이를 붙잡아 근거리를 유지해요. 수풀에 깔린 (E)\'묘목 던지기\'는 폭발하며 둔화를 걸 수 있으니 수풀 근처에서는 싸움을 피하세요.', lv6: '마오카이가 (R)\'대자연의 마수\'를 사용하면 벽이 천천히 전진하며 속박을 거니 벽이 오는 길 옆으로 비켜서세요. (R)\'돌겨어어억!!!\'의 보호막을 활용해 마오카이의 피해를 버티며 전투를 시작해요. 마오카이가 궁극기를 다른 라인에 사용한다면 빠르게 라인을 밀어 넣으며 압박하세요.', item: '마법 저항력과 강인함을 얻기 위해 헤르메스의 발걸음을 신발로 가세요. 공격력과 체력을 올려주는 갈라진 하늘을 첫 코어로 선택해요.', spell: '점멸과 점화를 추천해요. 마오카이는 (P)\'마법 흡수\'로 체력을 회복하므로 점화로 회복 효과를 감소시키며 싸우세요.' },
    '말자하': { lv1: '말자하가 (P)\'공허 태세\'로 피해 감소와 군중 제어 면역을 얻고 있으니, 먼저 평타나 (Q)\'덫날리기\'를 맞혀서 효과를 제거하세요. (Q)\'공허의 부름\' 투사체가 날아오는 위치를 잘 파악해서 피해와 침묵을 피해야 해요. 1~2레벨에는 말자하의 견제가 아프니 스칼의 용기를 잘 유지하며 거리를 조절하세요.', lv3: '말자하가 (E)\'재앙의 환상\'을 걸고 (W)\'공허의 무리\'를 소환하면 피해가 급격히 늘어나니 무리하게 싸우지 마세요. (E)\'이랴!\'를 사용해 빠르게 진입하여 (W)\'버럭버럭\'의 빠른 공격으로 짧게 딜교환을 하고 빠져나와야 해요. 상대의 (Q)\'공허의 부름\'이 빠진 타이밍을 노려 (Q)\'덫날리기\'로 거리를 좁히며 압박하세요.', lv6: '(R)\'황천의 손아귀\'는 제압 효과라 정화로 풀 수 없으니 말자하의 궁극기 사거리 안으로 무모하게 들어가지 마세요. (R)\'돌겨어어억!!!\'으로 보호막을 얻어 진입하더라도 제압 상태가 되면 스킬을 쓸 수 없으니 주의해야 해요. 말자하가 궁극기를 사용한 뒤에는 라인을 밀게 두면서 정글러의 도움을 기다리거나 스칼의 용기를 관리하세요.', item: '맬모셔스의 아귀를 첫 코어로 올려 마법 저항력을 챙기고 생존력을 높이세요. 신발은 마법 저항력을 제공하는 헤르메스의 발걸음을 신어주세요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\' 제압은 정화로 풀 수 없으니 점화로 킬각을 만드는 것이 좋아요.' },
    '말파이트': { lv1: '말파이트는 (P)\'화강암 방패\'로 피해를 흡수하며 (Q)\'지진의 파편\'으로 견제해요. (Q)\'지진의 파편\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없으니 주의하시고, 방패가 깨진 뒤에 (Q)\'덫날리기\'로 적을 끌어당기며 압박하세요. 초반에는 평타 교환으로 상대의 보호막을 빠르게 벗기는 것이 중요해요.', lv3: '(E)\'지면 강타\'를 맞으면 공격 속도가 감소해서 (W)\'버럭버럭\'의 공격 효율이 떨어지니 조심하세요. 말파이트가 (W)\'천둥소리\'를 켜고 평타를 치기 전에 (E)\'이랴!\'로 빠르게 접근해 먼저 공격하세요. (Q)\'덫날리기\'로 상대를 끌어당긴 뒤 짧게 딜교환하며 스칼의 용기를 채우는 방식으로 운영하세요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 막을 수 없으며, 맞으면 공중에 떠서 스킬을 쓸 수 없어요. 상대가 궁극기를 사용한 직후에 (R)\'돌겨어어억!!!\'으로 보호막을 얻으며 진입해 역습하세요. 정글러가 근처에 있을 때는 (R)\'멈출 수 없는 힘\'의 사거리 밖에서 라인을 관리하는 것이 안전해요.', item: '삼위일체를 선택해 공격력과 체력을 챙기고 강한 공격력으로 압박하세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 라인전에서 적절히 버티며 팀 교전에 빠르게 합류하는 것이 효율적이에요.' },
    '모데카이저': { lv1: '모데카이저의 (Q)\'말살\'은 범위 안의 적을 모두 때리고 단일 대상에게 맞으면 피해가 커지니 사거리 끝자락에서 거리를 조절하세요. (Q)\'덫날리기\'로 적을 끌어당겨 근접 전투를 시작하되 모데카이저의 (P)\'암흑 탄생\' 오라가 켜지지 않게 주의하며 스칼의 용기를 관리하세요.', lv3: '(E)\'죽음의 손아귀\'에 끌려오지 않도록 거리를 유지하며 모데카이저의 (Q)\'말살\'이 빠진 타이밍을 노려 (E)\'이랴!\'로 진입하세요. (W)\'버럭버럭\'을 켜고 빠르게 평타를 쳐서 교환한 뒤 모데카이저가 (W)\'불멸\'로 보호막을 두르기 전에 승부를 보세요.', lv6: '(R)\'죽음의 세계\'는 대상을 지정해 끌고 가며 그 안에서는 빠져나갈 수 없으니, 체력이 낮을 때는 모데카이저의 사거리 안에 머물지 마세요. 끌려갔다면 (Q)\'덫날리기\'와 (W)\'버럭버럭\'으로 맞서고, (R)\'죽음의 세계\'가 빠진 뒤에 (R)\'돌겨어어억!!!\'으로 보호막을 두르고 진입해 킬각을 보세요. (R)\'죽음의 세계\' 안에서는 정글러의 지원을 받을 수 없으니 라인을 당겨 관리하세요.', item: '갈라진 하늘을 첫 코어로 선택하여 체력과 공격력을 챙기며 교환을 이어가세요. 신발은 마법 저항력을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 모데카이저의 (W)\'불멸\' 체력 회복 효과를 줄여서 적을 마무리하기 쉬워요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'으로 현재 체력에 비례한 피해를 주고 둔화를 걸어요. 이 뼈톱은 처음 맞는 적에게 적중하므로 미니언 뒤에 서서 피하고, (E)\'이랴!\'를 사용해 빠르게 거리를 좁혀 짧게 공격하고 빠지세요. 통을 주워 체력을 회복하지 못하도록 계속 압박하는 것이 중요해요.', lv3: '(W)\'심장 전기 충격\'이 켜진 동안에는 받은 피해를 저장해 회복하므로, 이때는 무리하게 붙지 말고 거리를 유지하세요. (Q)\'덫날리기\'로 상대를 끌어당긴 뒤 (W)\'버럭버럭\'의 빠른 공격으로 빠르게 피해를 입히고 빠지는 식으로 딜교환하세요. 문도 박사의 체력이 많이 빠질수록 (E)\'둔기에 의한 외상\' 피해가 커지니 마무리 단계에서는 오래 끌지 말고 빠르게 끝내세요.', lv6: '(R)\'최대 투여량\'을 사용한 문도 박사는 엄청난 체력 회복과 이동 속도를 얻으므로, 궁극기가 빠진 것을 확인한 뒤 공격하세요. (R)\'돌겨어어억!!!\'으로 진입해 보호막을 얻으며 빠르게 접근하고, 상대의 회복량을 상회하는 피해를 입히는 것이 포인트예요. 정글러와 함께 공격할 때는 문도 박사의 (P)\'가고 싶은 데로 간다\' 때문에 첫 번째 이동 불가 효과가 무시될 수 있음을 기억하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력이 많은 상대에게 현재 체력 비례 피해를 넣고 생명력 흡수로 유지력을 높이세요. 신발은 (Q)\'오염된 뼈톱\'과 (W)\'심장 전기 충격\'의 마법 피해를 줄이고 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 문도 박사는 (R)\'최대 투여량\'과 패시브로 회복량이 매우 많으므로, 점화의 치유 감소 효과가 킬각을 잡는 데 필수적이에요.' },
    '바루스': { lv1: '바루스가 (Q)\'꿰뚫는 화살\'로 멀리서 견제하며 (W)\'역병 화살\' 중첩을 쌓으려 하니 사거리를 조심하며 거리를 좁히세요. 초반에는 무리하게 진입하기보다 미니언을 받아먹으며 (E)\'이랴!\'를 활용해 접근할 타이밍을 보세요.', lv3: '바루스가 (E)\'퍼붓는 화살\'로 지면을 오염시켜 이동 속도를 늦추고 회복을 줄이니 장판 위를 피하세요. (Q)\'덫날리기\'를 적중시켜 바루스를 끌어당긴 뒤 (W)\'버럭버럭\'의 공격 속도 증가를 활용해 몰아치세요. 바루스의 (W)\'역병 화살\' 중첩이 터지기 전에 빠르게 교환을 마쳐야 해요.', lv6: '바루스의 (R)\'부패의 사슬\'에 속박되면 (E)\'이랴!\' 같은 돌진은 쓸 수 없으니 궁극기를 맞지 않도록 위치를 잡으세요. (R)\'돌겨어어억!!!\'으로 보호막을 얻으며 돌진해 압박하고 스칼이 적을 밀어낸 직후 (Q)\'덫날리기\'로 굳히세요. 라인을 당겨두었다가 바루스가 궁극기를 빗맞힌 시점에 정글러와 함께 노리세요.', item: '첫 코어로 갈라진 하늘을 선택해 체력과 공격력을 챙기며 전투 지속력을 높이세요. 신발은 바루스의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 바루스의 견제 거리를 빠르게 뚫고 접근하세요.' },
    '베인': { lv1: '베인은 (Q)\'구르기\'로 거리를 조절하며 (W)\'은화살\'로 최대 체력 비례 고정 피해를 입히니 정면 교전은 피하세요. 스칼의 체력을 보존하며 미니언 뒤에서 버티다가 베인이 사거리 안으로 들어오면 (E)\'이랴!\'로 빠르게 접근해 압박하세요.', lv3: '베인의 (E)\'선고\'에 맞아 벽에 부딪히면 기절하니 항상 벽에서 떨어져서 싸우세요. 베인이 (E)\'선고\'를 사용한 직후에 (Q)\'덫날리기\'를 맞혀 끌어당기고 (W)\'버럭버럭\'의 빠른 공격으로 몰아치세요. (E)\'이랴!\'의 재사용 돌진으로 (Q)\'구르기\'로 빠지는 베인을 따라붙으세요.', lv6: '베인이 (R)\'결전의 시간\'을 켜면 (Q)\'구르기\' 사용 시 투명 상태가 되어 접근하기 까다로워요. 투명해지기 전 (R)\'돌겨어어억!!!\'으로 진입해 보호막으로 (W)\'은화살\' 피해를 버티며 딜교환을 하세요. 라인을 밀어 넣고 정글러를 호출해 빠르게 정리하는 구도를 만드세요.', item: '삼위일체로 공격력과 체력을 챙겨 베인과의 교전에서 유지력을 높이세요. 신발은 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 베인의 낮은 체력을 이용해 (Q)\'덫날리기\' 적중 후 점화로 확실하게 마무리하세요.' },
    '볼리베어': { lv1: '1~2레벨에는 볼리베어가 (Q)\'번개 강타\'를 사용하여 기절을 시키며 접근하는 것에 주의하세요. 볼리베어의 (Q)\'번개 강타\'가 빠지기 전에는 무리하게 붙지 말고 거리를 유지하며 견제하세요. (Q)\'덫날리기\'를 활용해 적과의 거리를 조절하며 짧게 교환하는 것이 좋아요.', lv3: '볼리베어가 (E)\'천공 분열\'을 사용하면 번개가 떨어지는 범위 밖으로 벗어나 피해와 둔화를 피하세요. (W)\'광란의 상처\' 표식이 남은 상태에서 볼리베어가 체력을 회복할 수 있으니 표식이 남았다면 즉시 거리를 두세요. 볼리베어의 (Q)\'번개 강타\'가 빠진 뒤에 (E)\'이랴!\'로 진입해 (Q)\'덫날리기\'를 맞히세요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'로 포탑을 비활성화하며 진입할 수 있으니 체력이 낮을 때 포탑 아래에 있지 마세요. 볼리베어가 도약할 때 (R)\'돌겨어어억!!!\'을 사용해 보호막으로 피해를 흡수하고 스칼로 밀쳐내세요. 볼리베어의 (R)\'폭풍을 부르는 자\'가 빠진 뒤에 (E)\'이랴!\'를 활용해 적극적으로 싸우세요.', item: '첫 코어 아이템으로 삼위일체를 가서 교전 능력을 높이세요. 신발은 (Q)\'번개 강타\'의 기절 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 볼리베어가 (W)\'광란의 상처\'로 체력을 회복하는 것을 점화로 억제하세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 계속 체력을 흡수하며 견제해요. (Q)\'수혈\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 맞으니, 스칼의 체력으로 버티며 거리를 유지하세요. 상대가 막타를 치러 다가오면 (W)\'버럭버럭\'의 빠른 기본 공격을 넣어 체력을 깎으세요.', lv3: '블라디미르가 (W)\'피의 웅덩이\'를 쓰면 대상 지정이 안 되니, 웅덩이가 끝나는 타이밍에 맞춰 (E)\'이랴!\'로 돌진하세요. (E)\'선혈의 파도\'는 미니언이 막아주니 꼭 미니언 뒤에서 피해 주세요. (Q)\'덫날리기\'로 상대를 붙잡은 뒤 (W)\'버럭버럭\' 네 번째 공격까지 빠르게 꽂아 넣는 것이 중요해요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니, 감염된 동안에는 무리하게 싸우지 말고 거리를 벌리세요. 블라디미르의 (W)\'피의 웅덩이\'가 빠진 것을 확인한 뒤 (R)\'돌겨어어억!!!\'으로 진입해 보호막을 활용하며 강하게 압박하세요. 정글러가 왔을 때 (Q)\'덫날리기\'로 상대를 붙잡아 두면 쉽게 처치할 수 있어요.', item: '맬모셔스의 아귀를 가서 마법 저항력을 높이고 생명선 보호막으로 생존력을 높이세요. 신발은 마법 저항력과 강인함이 있는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 블라디미르는 (Q)\'수혈\'로 체력을 계속 회복하므로 점화의 치유 감소 효과가 반드시 필요해요.' },
    '뽀삐': { lv1: '뽀삐가 (Q)\'망치 강타\'로 첫 타격을 입히면 둔화 지대가 생기니 즉시 그 범위에서 벗어나세요. (P)\'강철의 외교관\'으로 생성된 방패를 주워 보호막을 얻기 전에 (Q)\'덫날리기\'로 붙잡아 짧게 교환하며 압박하세요. 스칼의 체력을 유지하며 뽀삐가 방패를 줍기 위해 움직이는 타이밍을 노려 공격하세요.', lv3: '뽀삐가 (W)\'굳건한 태세\'를 켜면 (E)\'이랴!\' 돌진이 막히고 둔화되니 스킬이 끝날 때까지 기다렸다가 진입하세요. (E)\'용감한 돌진\'에 밀려 벽에 부딪히면 기절하므로 가급적 라인 중앙에서 싸우며 거리 조절을 하세요. (W)\'버럭버럭\'의 빠른 공격으로 압박하되 뽀삐의 돌진 차단 스킬이 빠진 것을 확인하고 공격을 마무리하세요.', lv6: '뽀삐가 (R)\'수호자의 심판\'을 충전해 멀리 날려버리려 하면 즉시 범위 밖으로 벗어나 흐름이 끊기지 않게 하세요. (R)\'돌겨어어억!!!\'의 보호막으로 진입하되 뽀삐가 (W)\'굳건한 태세\'로 돌진을 막지 못하도록 타이밍을 늦춰 사용하세요. (Q)\'덫날리기\'로 적을 끌어당긴 뒤 뽀삐가 밀어낼 틈 없이 강하게 몰아붙여 킬각을 잡으세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격 속도와 체력을 챙겨 지속 교전 능력을 높이고 판금 장화로 뽀삐의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 점화로 초반 교전에서 뽀삐의 체력을 빠르게 깎아 처치하세요.' },
    '사이온': { lv1: '사이온이 (E)\'학살자의 포효\'를 사용하면 미니언을 맞히고 뒤의 적에게도 방어력을 낮추는 효과를 주니 미니언 뒤에 숨지 마세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하는 동안에는 범위 밖으로 비켜서서 피해를 피하고 빈틈에 (Q)\'덫날리기\'를 사용하세요.', lv3: '사이온이 (W)\'영혼의 용광로\'를 사용해 보호막을 얻으면 잠시 뒤 폭발하므로 폭발 지점에서 멀어지도록 거리 조절을 하세요. 사이온의 (Q)\'대량 학살 강타\'가 빠진 것을 확인한 뒤 (E)\'이랴!\'로 접근하여 (W)\'버럭버럭\'을 활용해 딜교환을 하세요.', lv6: '사이온이 (R)\'멈출 수 없는 맹공\'으로 돌진할 때는 옆으로 비켜서서 기절을 피하고 (R)\'돌겨어어억!!!\'으로 보호막을 얻으며 맞서세요. 사이온이 처치되어도 (P)\'영광스러운 죽음\'으로 잠시 되살아나니 처치한 직후에는 바로 거리를 두세요. 사이온이 라인을 밀도록 유도해 정글러의 도움을 받으세요.', item: '첫 코어로 삼위일체를 선택해 전투 능력을 높이세요. 신발은 물리 피해 위주인 사이온을 상대로 기본 공격 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 사이온은 라인을 밀어두는 성향이 강하니 순간이동으로 라인 복귀를 도와 손해를 최소화하세요.' },
    '사일러스': { lv1: '사일러스가 (Q)\'사슬 후려치기\'로 견제하며 (P)\'페트리사이트 폭발\' 평타를 섞어 쓸 때 거리를 조절하세요. (E)\'이랴!\'로 빠르게 접근해 (W)\'버럭버럭\'의 마지막 공격을 맞히며 강하게 압박하세요. 사슬이 교차하는 지점의 폭발 피해를 피하며 스칼의 체력을 유지하는 것이 중요해요.', lv3: '(E)\'도주 / 억압\'의 재사용 사슬에 맞으면 공중으로 띄워지니 옆으로 움직여 피한 뒤 (Q)\'덫날리기\'로 붙잡으세요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하기 전에 (W)\'버럭버럭\'의 빠른 공격을 쏟아내세요. (E)\'이랴!\'의 재사용 돌진을 섞어 짧게 딜교환하고 빠지세요.', lv6: '사일러스가 (R)\'강탈\'로 내 궁극기를 훔쳐 (R)\'돌겨어어억!!!\'을 쓸 수 있으니 진입 각을 미리 보고 거리를 벌리세요. 내가 (R)\'돌겨어어억!!!\'의 보호막으로 진입할 때는 사일러스가 (W)\'국왕시해자\'로 회복할 틈 없이 밀어붙이세요. 정글러가 올 때 (Q)\'덫날리기\'로 적을 붙잡아 함께 처치하세요.', item: '갈라진 하늘을 첫 코어로 가서 체력을 높이고 공격 시 체력을 회복하며 버티세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음으로 사일러스의 군중 제어 지속시간을 줄이는 것이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'국왕시해자\'의 체력 회복 효과를 감소시켜 킬각을 잡으세요.' },
    '세주아니': { lv1: '1~2레벨에는 (E)\'이랴!\'를 사용해 빠르게 접근한 뒤 (W)\'버럭버럭\'으로 강하게 공격하세요. 상대가 (Q)\'혹한의 맹습\'으로 공중으로 띄우려 할 때 거리를 조절하며 피해를 최소화해야 해요. 스칼의 체력을 유지하며 짧은 딜교환을 반복하세요.', lv3: '(Q)\'덫날리기\'를 적중시켜 상대를 끌어당기며 (W)\'버럭버럭\'의 네 번째 공격을 맞히세요. 상대의 (Q)\'혹한의 맹습\'이 빠진 것을 확인하고 (E)\'이랴!\'로 진입하는 것이 중요해요. (E)\'만년 서리\'는 세주아니 쪽 근접 아군의 기본 공격으로 쌓이니 아군 근접 챔피언이 곁에 있을 때는 무리하지 마세요.', lv6: '(R)\'빙하 감옥\'은 처음 맞힌 챔피언을 기절시키니 맞으면 그동안 스킬을 쓸 수 없어요. 세주아니가 궁극기를 빗맞히거나 다른 곳에 쓴 뒤 (R)\'돌겨어어억!!!\'의 보호막을 두르고 진입해 킬각을 잡으세요. (E)\'이랴!\'의 재사용 돌진으로 다시 붙어 상대의 도주 경로를 차단하세요.', item: '헤르메스의 발걸음과 삼위일체를 추천해요. 강인함으로 기절 시간을 줄이고 공격력과 체력을 높여 지속 전투 능력을 강화하세요.', spell: '점멸과 점화를 추천해요. 순간적인 거리 좁히기로 킬각을 잡고 점화의 고정 피해로 상대를 확실히 마무리하세요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'으로 빠르게 접근해 최대 체력 비례 피해를 입히며 (P)\'투기장의 투지\'로 체력을 회복해요. 무리하게 붙어 싸우기보다 (E)\'이랴!\'로 빠르게 접근했다가 빠지며 딜교환을 짧게 가져가세요. 세트의 기본 공격 연계가 시작되기 전에 거리를 벌려 피해를 최소화하세요.', lv3: '(E)\'안면 강타\'는 양옆의 적을 끌어당겨 기절시키고 한쪽뿐이면 둔화시키니, 세트의 양옆에 서지 않도록 주의하세요. 세트의 투지가 가득 찼을 때는 (W)\'강펀치\'의 고정 피해가 강력하므로 중심선에서 벗어나도록 움직이며 스킬이 빠지길 기다리세요. 스킬이 빠진 뒤 (W)\'버럭버럭\'의 빠른 공격으로 압박하고 (Q)\'덫날리기\'로 붙잡아 짧게 교환하세요.', lv6: '(R)\'대미 장식\'은 나를 제압해 내리꽂으므로, 세트가 나를 붙잡기 전에 (R)\'돌겨어어억!!!\'의 보호막으로 피해를 흡수하며 진입하세요. 세트가 궁극기를 사용한 뒤에는 잠시 공백이 생기므로 (E)\'이랴!\'로 다시 붙어 공격을 퍼부으세요. (R)\'대미 장식\'에 잡혀 내리꽂히면 주변 적들이 둔화되니 정글러의 개입이 있을 때 주의하세요.', item: '삼위일체를 가서 공격 속도와 체력을 챙겨 (W)\'버럭버럭\'의 효율을 높이세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'투기장의 투지\'로 체력을 회복하는 세트에게 점화의 치유 감소 효과가 유용해요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 주고 (P)\'기 보호막\'으로 피해를 흡수해요. (E)\'이랴!\'로 빠르게 진입해 공격하되, 쉔의 보호막이 켜져 있을 때는 무리하게 딜교환하지 마세요. 쉔이 (Q)\'황혼 강습\'을 사용해 기의 검을 불러들인 뒤 보호막이 사라지는 시점에 평타 공격을 넣으세요.', lv3: '쉔의 (W)\'의지의 결계\'가 켜진 동안은 평타가 막히니 (W)\'버럭버럭\'의 공격 속도 증가를 아끼고 (Q)\'덫날리기\'로 먼저 거리를 좁히세요. (E)\'그림자 돌진\'에 도발되면 스킬을 쓸 수 없으니, 쉔이 돌진하기 전에 (E)\'이랴!\'로 먼저 진입해 딜교환을 주도하세요. 쉔의 도발이 빠진 뒤에 (W)\'버럭버럭\'의 네 번째 공격까지 모두 맞히면 큰 피해를 줄 수 있어요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 두르고 진입해 쉔의 (Q)\'황혼 강습\'과 (E)\'그림자 돌진\' 피해를 버티며 압박하세요. 도발당하는 동안은 스킬을 쓸 수 없으니 (E)\'그림자 돌진\'이 빠진 것을 확인한 뒤 들어가세요. 쉔이 (R)\'단결된 의지\'로 다른 라인에 합류하면 빠르게 라인을 밀어 포탑에 피해를 입히세요.', item: '삼위일체를 첫 코어로 선택해 공격력과 체력을 챙기고 빠른 공격 속도로 쉔을 압박하세요. 신발은 (E)\'그림자 돌진\'의 도발 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 쉔의 (P)\'기 보호막\'이 빠진 타이밍에 점화를 켜서 빠르게 체력을 깎아 킬각을 잡으세요.' },
    '쉬바나': { lv1: '1~2레벨에는 (Q)\'잉걸불 일격\'의 피해를 조심하며 거리를 유지하세요. (E)\'이랴!\'를 사용하여 빠르게 접근해 스칼의 용기를 확보하며 압박을 시작해요. 상대가 미니언 근처에서 스킬을 쓰려 하면 뒤로 물러나며 대응하세요.', lv3: '(Q)\'덫날리기\'로 상대를 붙잡은 뒤 (W)\'버럭버럭\'을 사용하여 빠르게 딜교환을 해요. 상대가 (W)\'지옥불 방패\'를 사용하여 보호막을 생성하면 무리하게 진입하지 말고 폭발을 기다리세요. (E)\'이랴!\'를 활용해 상대의 스킬 범위를 벗어나며 싸워요.', lv6: '상대가 (R)\'용의 강림\'을 사용하여 용으로 변신하면 (R)\'돌겨어어억!!!\'의 보호막을 활용해 맞서세요. 용 형상의 공격이 강력하니 체력 관리에 유의하며 정글러의 도움을 요청해요. 라인을 밀어 넣고 상대가 변신을 유지하기 위해 분노를 쌓지 못하도록 견제해요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 헤르메스의 발걸음은 마법 저항력과 강인함을 제공해요. 갈라진 하늘은 공격력과 체력을 제공해요.', spell: '점멸과 점화예요. 점멸은 순간적인 위치 변화로 (R)\'용의 강림\'을 피하거나 진입할 때 사용해요. 점화는 상대의 체력 회복 효과를 감소시키며 킬을 노리기에 좋아요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 견제하며 (P)\'굶주린 새떼\'로 체력을 회복해요. 스웨인이 (Q)\'죽음의 손길\'을 쓰려고 할 때 (E)\'이랴!\'로 거리를 좁히며 빠르게 접근하세요. 스웨인이 영혼 조각을 모아 최대 체력을 늘리기 전에 먼저 압박하는 것이 중요해요.', lv3: '스웨인이 (E)\'속박명령\'을 사용하면 파동이 돌아올 때 옆으로 움직여 속박을 피하세요. (E)\'속박명령\'에 걸리면 끌려갈 수 있으니 주의해야 해요. 스웨인의 (W)\'제국의 눈\'이 빠졌다면 (Q)\'덫날리기\'로 스웨인을 붙잡고 (W)\'버럭버럭\'을 활용해 딜교환을 하세요.', lv6: '스웨인이 (R)\'악의 승천\'을 사용하면 주변의 체력을 흡수하니 미니언이 많은 곳에서 오래 싸우지 마세요. (R)\'돌겨어어억!!!\'으로 보호막을 얻으며 돌진하고 (Q)\'덫날리기\'를 사용하여 거리를 조절하세요. 스웨인이 변신한 상태에서는 무리하게 맞서지 말고 정글러와 함께 압박하세요.', item: '첫 코어로 굶주린 히드라를 가고 신발은 헤르메스의 발걸음을 선택하세요. 굶주린 히드라의 생명력 흡수로 스웨인의 견제를 버티고 헤르메스의 발걸음으로 스웨인의 군중 제어 지속시간을 줄여야 해요.', spell: '점멸과 점화를 추천해요. 스웨인은 (R)\'악의 승천\'과 (P)\'굶주린 새떼\'로 체력을 회복하니 점화로 회복 효과를 줄여야 해요.' },
    '스카너': { lv1: '스카너 (Q)\'부서진 대지/지반 돌출\'의 둔화와 피해를 조심하며 거리를 조절하세요. (Q)\'덫날리기\'를 활용해 스카너가 접근하기 전에 견제하며 스칼의 용기를 관리하는 것이 중요해요. 초반에는 무리하게 싸우기보다 미니언을 챙기며 상황을 지켜보세요.', lv3: '스카너의 (E)\'이쉬탈의 격돌\'이 벽에 부딪혀 기절시키지 못하도록 지형 근처에서 주의하며 싸우세요. (W)\'대지의 수호자\'가 빠진 것을 확인한 뒤 (W)\'버럭버럭\'과 (Q)\'덫날리기\'를 연계해 딜교환을 해요. (E)\'이랴!\'를 사용하여 스카너의 돌진을 따라가거나 거리를 조절하세요.', lv6: '스카너의 (R)\'꿰뚫기\'에 제압당해 끌려다니는 상황을 가장 조심해야 해요. 스카너가 궁극기를 사용했다면 (R)\'돌겨어어억!!!\'의 보호막을 이용해 맞대응하거나 거리를 벌리세요. 라인을 빠르게 밀어 정글러의 개입에 대비하는 것이 좋아요.', item: '판금 장화와 굶주린 히드라를 추천해요. 판금 장화로 스카너의 기본 공격 피해를 줄이고 굶주린 히드라로 전투 지속력을 높여요.', spell: '점멸과 점화. 점멸로 스카너의 (E)\'이쉬탈의 격돌\'을 피하고 점화로 적의 체력을 낮춰 킬을 노려요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'를 켜고 라인을 밀며 뒤에 독구름을 남겨요. 스칼이 체력을 대신 받아주니 무리하게 쫓지 말고 막타를 챙기며 (W)\'버럭버럭\'으로 짧게 딜교환하세요. 독구름 위에서 오래 싸우면 스칼의 체력이 빠르게 빠지니 주의하세요.', lv3: '(W)\'초강력 접착제\' 위에서는 (E)\'이랴!\' 같은 이동 스킬을 쓸 수 없으니 접착제가 깔린 곳은 피하세요. 신지드가 (E)\'던져넘기기\'로 던지려 근접해 올 때는 접착제 위에 서지 않도록 위치를 잡으세요. (W)\'초강력 접착제\'가 빠진 것을 확인한 뒤 (E)\'이랴!\'로 진입해 (W)\'버럭버럭\' 공격을 다 맞히세요.', lv6: '(R)\'광기의 물약\'을 마신 신지드는 체력 재생력과 방어력이 높아지니 효과가 끝날 때까지 기다리세요. 신지드가 라인을 밀어낼 때 (R)\'돌겨어어억!!!\'으로 진입하면 보호막 덕분에 (Q)\'맹독의 자취\' 피해를 견디며 공격할 수 있어요. (W)\'초강력 접착제\'가 깔려 있지 않은 경로로 돌진해 신지드를 밀어내고 빠르게 정리하세요.', item: '삼위일체로 공격력과 체력을 보충해 정면 싸움에서 앞서세요. 신발은 마법 저항력을 높이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 피해로 체력이 낮은 신지드를 마무리하고 (R)\'광기의 물약\'의 체력 재생력을 억제하세요.' },
    '신짜오': { lv1: '신짜오의 (Q)\'삼조격\' 에어본과 (P)\'결심\' 회복이 강력한 구간이에요. (Q)\'덫날리기\'로 적과의 거리를 유지하며 스칼의 용기를 관리하는 것이 중요해요. 무리한 교전보다는 미니언을 챙기며 다음 단계를 준비하세요.', lv3: '신짜오가 (E)\'무쌍돌격\'으로 돌진할 때 (E)\'이랴!\'를 사용하여 대응하거나 거리를 벌려야 해요. 상대의 (W)\'풍전참뢰\' 둔화를 피하면서 (Q)\'덫날리기\'를 적중시켜 딜교환을 시도해요. 신짜오의 (Q)\'삼조격\' 공격을 맞지 않도록 주의하며 싸우세요.', lv6: '(R)\'돌겨어어억!!!\'은 상황에 따라 보호막을 두르고 싸움을 거는 용도나 위험할 때 빠져나오는 용도 중 하나로 쓰세요. 신짜오가 (R)\'현월수호\'를 쓰면 창이 닿는 거리 밖에서 오는 피해를 받지 않으니, 밀려났다면 (E)\'이랴!\'로 다시 붙어서 싸우세요. 스칼이 내리면 위험하니 라인을 당겨 관리하며 정글의 지원을 요청하세요.', item: '판금 장화와 굶주린 히드라를 가세요. 신짜오의 물리 피해를 줄이기 위해 판금 장화가 필요하고 굶주린 히드라로 생명력 흡수를 챙겨요.', spell: '점멸과 점화. 점멸로 상대의 기술을 피하고 점화로 상대의 회복 효과를 줄여요.' },
    '아이번': { lv1: '1~2레벨에는 아이번의 (Q)\'덩굴뿌리\' 사거리가 매우 길어 견제가 심해요. 미니언 뒤에 숨어 (Q)\'덩굴뿌리\'를 막아내고 (E)\'이랴!\'로 빠르게 접근해 스칼의 체력을 유지하세요.', lv3: '(Q)\'덩굴뿌리\'가 빠진 것을 확인한 뒤 (Q)\'덫날리기\'로 아이번을 끌어당겨 딜교환을 시작하세요. (W)\'버럭버럭\'의 빠른 공격으로 체력을 깎되 (E)\'보호의 씨앗\' 폭발로 인한 둔화를 조심하며 추격해요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 활용해 진입하여 아이번을 압박하세요. (R)\'데이지!\'가 소환되면 데이지의 충격파로 인해 공중에 뜰 수 있으니 거리를 조절하며 싸워야 해요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 마법 저항력과 강인함으로 (Q)\'덩굴뿌리\' 속박 지속시간을 줄이고 체력을 높여 생존력을 확보하세요.', spell: '점멸과 점화를 추천해요. 점멸로 진입 각을 만들어 접근력을 보완하고, 점화로 마무리 피해를 더해 킬각을 잡으세요.' },
    '아지르': { lv1: '아지르가 (W)\'일어나라!\'로 계속 견제하므로 스칼의 체력 관리에 집중하세요. (Q)\'사막의 맹습\'의 둔화를 조심하며 (E)\'이랴!\'를 사용해 거리 조절을 하세요. 무리하게 진입하기보다 미니언 뒤에서 버티며 기회를 보세요.', lv3: '아지르의 (E)\'신기루\'가 빠진 순간이 진입 적기예요. (Q)\'덫날리기\'로 상대를 붙잡은 뒤 (W)\'버럭버럭\'으로 빠르게 공격하세요. (Q)\'사막의 맹습\'에 둔화되면 다시 (E)\'이랴!\'를 사용해 추격하세요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 활용해 진입하되 상대의 (R)\'황제의 진영\'에 밀려나지 않게 주의하세요. 상대 궁극기가 빠졌다면 (E)\'이랴!\'와 함께 과감하게 킬각을 보세요. 정글러를 불러 (Q)\'사막의 맹습\' 거리 밖에서 기습하는 것이 편해요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 마법 저항력과 강인함을 얻고 체력과 공격력으로 스칼의 유지력을 높여요.', spell: '점멸과 순간이동을 사용하세요. 점멸로 (Q)\'덫날리기\' 각을 만들고 순간이동으로 라인 복귀를 빠르게 해요.' },
    '아칼리': { lv1: '아칼리는 (Q)\'오연투척검\'으로 둔화를 걸며 견제하고 (P)\'암살자의 표식\' 원을 이용해 강화 평타를 노려요. (E)\'이랴!\'로 빠르게 접근해 (W)\'버럭버럭\'의 빠른 공격으로 체력을 깎으세요. 아칼리가 기력을 다 쓰도록 유도하며 스칼의 체력을 유지하는 게 중요해요.', lv3: '(W)\'황혼의 장막\' 안의 아칼리는 대상 지정이 안 되지만 (Q)\'덫날리기\'는 대상 지정이 아니라 그대로 맞힐 수 있으니, 연막에서 나오는 방향을 보고 던지세요. (E)\'표창곡예\' 표식이 남았을 때 아칼리가 돌진해 들어오면 (W)\'버럭버럭\'으로 맞대응해 피해를 입히세요. (E)\'이랴!\'를 이용해 아칼리의 표창 사거리 밖으로 빠졌다가 다시 진입하는 구도를 만드세요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 활용해 (R)\'무결처형\'의 폭발적인 피해를 흡수하며 진입하세요. 아칼리가 (W)\'황혼의 장막\'으로 숨어 대상 지정이 안 될 때는 무리하게 쫓지 말고 라인을 밀어 포탑으로 압박하세요. 정글러가 개입할 때는 아칼리의 도주기인 (E)\'표창곡예\'가 빠진 시점을 노려 킬각을 잡으세요.', item: '맬모셔스의 아귀를 가서 아칼리의 순간적인 마법 피해를 생명선 보호막으로 버티세요. 신발은 마법 저항력을 높이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 아칼리의 체력을 깎고 마무리 피해를 더해 빠르게 처치하세요.' },
    '아크샨': { lv1: '상대가 (Q)\'복수의 부메랑\'으로 계속 견제할 때 스칼의 체력을 이용해 버티며 경험치를 챙기세요. (E)\'이랴!\'로 무리하게 들어가기보다는 첫 웨이브를 안전하게 받으며 거리를 조절해요. 아크샨이 (P)\'비열한 싸움\'으로 보호막을 얻기 전에 빠르게 교전하는 것이 좋아요.', lv3: '(W)\'버럭버럭\'을 사용해 빠르게 공격하며 상대의 원거리 견제를 무시하고 피해를 입히세요. 아크샨이 (E)\'영웅의 비상\'으로 거리를 벌리려 할 때 (Q)\'덫날리기\'로 적을 끌어당겨 추격을 이어가요. 상대의 (Q)\'복수의 부메랑\'이 돌아올 때까지 기다렸다가 진입하는 것이 좋아요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 두르고 진입해 상대의 (R)\'인과응보\' 피해를 흡수하며 거리 차이를 좁히세요. 아크샨이 (E)\'영웅의 비상\'으로 벽을 타며 도망가면 (E)\'이랴!\'와 (Q)\'덫날리기\'로 따라붙어 킬각을 잡는 것이 좋아요. 정글러가 올 때 (Q)\'덫날리기\'로 적을 끌어당기면 함께 처치하기 편해요.', item: '판금 장화와 삼위일체를 추천해요. 판금 장화는 아크샨의 기본 공격 피해를 줄여주고 삼위일체는 공격력과 체력을 모두 보강해줘요.', spell: '점멸과 점화를 추천해요. (P)\'비열한 싸움\' 보호막이 빠진 뒤 점화로 마무리 피해를 더해 확실하게 처치하세요.' },
    '아트록스': { lv1: '아트록스는 (Q)\'다르킨의 검\' 끝자락에 맞으면 공중으로 떠오르니 범위를 잘 피하며 미니언을 챙기세요. (E)\'이랴!\'를 사용해 거리 조절을 하며 아트록스의 스킬 낭비를 유도하세요. 스칼의 용기가 충분할 때만 (Q)\'덫날리기\'로 짧게 딜교환을 시도해요.', lv3: '아트록스의 (W)\'지옥사슬\' 중앙에 맞지 않도록 (E)\'이랴!\'로 거리를 조절하며 움직이세요. 아트록스가 (Q)\'다르킨의 검\'을 사용한 직후에 (E)\'이랴!\'로 돌진하여 (Q)\'덫날리기\'를 맞히며 딜교환을 해요. 아트록스의 (E)\'파멸의 돌진\'이 빠진 시점에 (W)\'버럭버럭\'을 켜고 몰아붙이세요.', lv6: '아트록스가 (R)\'세계의 종결자\'를 사용하면 공격력과 체력 회복량이 늘어나니 정면 싸움은 피하세요. (R)\'돌겨어어억!!!\'의 보호막을 활용해 아트록스의 스킬을 버티며 스칼을 다시 태우는 것이 중요해요. 라인을 밀어 넣어 정글러의 개입을 유도하며 아트록스의 스킬을 빼도록 만드세요.', item: '전투력을 높이기 위해 삼위일체를 첫 코어로 올려요. 신발은 아트록스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화는 아트록스의 (P)\'사신 태세\'와 (E)\'파멸의 돌진\'을 통한 체력 회복을 억제하는 데 도움을 줘요.' },
    '암베사': { lv1: '암베사는 스킬을 사용한 뒤 (P)\'용사냥개의 발걸음\'으로 돌진하며 다음 기본 공격을 강화해요. 암베사가 (Q)\'교활한 휩쓸기\'로 접근할 때 (Q)\'덫날리기\'를 사용해 거리를 조절하며 견제하세요. 암베사가 스킬을 쓰고 돌진할 때 (E)\'이랴!\'로 빠르게 거리를 벌리는 것이 좋아요.', lv3: '암베사가 (W)\'배척\'을 준비하며 보호막을 얻을 때는 (W)\'버럭버럭\'을 활용한 강력한 딜교환을 잠시 멈추세요. (E)\'찢어 가르기\'의 둔화에 걸리지 않도록 (E)\'이랴!\'를 사용하여 암베사의 스킬을 피하며 파고드세요. (Q)\'덫날리기\'로 암베사를 붙잡은 뒤 (W)\'버럭버럭\'의 네 번째 공격을 맞춰 최대한의 피해를 입히세요.', lv6: '암베사의 (R)\'공개 처형\'은 제압을 거는 강력한 스킬이니 멀리서 타겟이 되지 않도록 주의하세요. 제압 상태에서는 (R)\'돌겨어어억!!!\'을 포함한 모든 스킬을 사용할 수 없으니 체력 관리가 중요해요. 암베사가 궁극기를 사용한 직후에 (R)\'돌겨어어억!!!\'으로 거리를 벌리거나 역으로 진입해 싸우세요.', item: '몰락한 왕의 검을 첫 코어로 가서 암베사의 체력을 깎고 전투를 지속하세요. 신발은 암베사의 기본 공격 피해를 줄이기 위해 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 암베사는 (R)\'공개 처형\'의 기본 지속 효과로 스킬 피해의 일부만큼 체력을 회복하니 점화로 회복을 줄이며 마무리하세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\' 구체를 날려 기절시키고 (E)\'동상\'으로 강하게 견제해요. 구체가 날아오는 경로를 피해 옆으로 움직이며 스칼의 체력을 유지하세요. (E)\'이랴!\'를 사용해 빠르게 접근하려 하지만 구체에 맞으면 기절하니 주의하세요.', lv3: '(W)\'결정화\' 벽이 생기면 진입 경로가 막히니 벽이 사라진 후에 (E)\'이랴!\'로 빠르게 붙으세요. (Q)\'냉기 폭발\'이 빠진 시점에 (Q)\'덫날리기\'를 맞춰 끌어당기면 애니비아를 가까이 붙잡고 딜교환을 이어갈 수 있어요. (W)\'버럭버럭\'을 켜고 빠르게 공격해 스칼의 용기를 회복하며 압박하세요.', lv6: '(R)\'얼음 폭풍\'의 둔화와 피해를 (R)\'돌겨어어억!!!\' 보호막으로 견디며 빠르게 진입하세요. 애니비아가 (P)\'환생\'으로 알이 되었다가 다시 나오는 순간에 대비해 스킬과 체력을 남겨 두세요. 정글러가 올 때 (W)\'결정화\' 벽에 갇히지 않도록 측면으로 접근하세요.', item: '맬모셔스의 아귀를 가서 마법 피해를 견디고 공격력을 높이세요. 신발은 (Q)\'냉기 폭발\' 기절과 (R)\'얼음 폭풍\' 둔화 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점멸로 (W)\'결정화\' 벽을 넘거나 접근하고 점화로 확실하게 마무리하세요.' },
    '야스오': { lv1: '야스오는 (P)\'낭인의 길\' 보호막이 있으니 평타로 먼저 터뜨린 뒤 (E)\'이랴!\'로 돌진해 교전하세요. (Q)\'강철 폭풍\' 회오리바람이 쌓였을 때는 거리를 벌려 띄워지는 상황을 피하는 것이 중요해요. 첫 웨이브부터 강하게 압박하기보다 스칼의 체력을 관리하며 적절한 타이밍에 진입하세요.', lv3: '(Q)\'덫날리기\'는 투사체라 야스오의 (W)\'바람 장막\'에 막히니, 장막이 사라진 것을 확인하고 사용하세요. (W)\'버럭버럭\'의 빠른 공격으로 (Q)\'강철 폭풍\'의 회오리가 나오기 전에 딜교환을 마치고 빠지는 것이 좋아요. (E)\'이랴!\'로 진입해 거리를 좁힌 뒤 빠른 평타 공격으로 스칼의 용기를 빠르게 회복하세요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 활용해 과감하게 진입하되, (Q)\'강철 폭풍\' 회오리에 맞으면 (R)\'최후의 숨결\'로 이어지니 주의하세요. 스칼에서 내렸을 때는 (Q)\'덫날리기\'가 바뀐 원거리 공격으로 용기를 회복하며 야스오의 (E)\'질풍검\' 진입 각을 제한하세요. 라인을 밀어두고 정글러와 함께 덮치면 야스오가 (W)\'바람 장막\' 하나로 버티기 힘들어요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 체력을 높여 교전 능력을 올리고, 판금 장화로 야스오의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'낭인의 길\' 보호막 이후 마무리 피해를 더해 킬각을 잡으세요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리가 늘어난 평타를 치며 방어력을 깎고 (P)\'바위 피부\'로 갈수록 단단해져요. (E)\'이랴!\'로 진입해 짧게 딜교환을 하고 빠지며 스칼의 체력을 관리하세요. (Q)\'파쇄격\'의 사거리에 계속 노출되지 않도록 거리 조절을 하는 게 중요해요.', lv3: '(W)\'분신 전사\'가 남긴 분신에 (Q)\'덫날리기\'를 낭비하면 오공의 돌격에 무방비해지니 주의하세요. (E)\'근두운 급습\'으로 들어오는 오공에게 (W)\'버럭버럭\'의 빠른 공격으로 피해를 입히세요. 오공이 투명 상태로 사라지면 (E)\'이랴!\'를 아꼈다가 진짜 오공이 나타나는 방향으로 쓰세요.', lv6: '(R)\'회전격\'에 맞으면 공중에 떠서 아무 스킬도 쓸 수 없으니 오공이 여의봉을 휘두를 때 정면으로 맞서지 마세요. (R)\'돌겨어어억!!!\'은 오공이 (R)\'회전격\'을 쓴 뒤에 보호막을 두르고 진입하는 용도로 아껴 두세요. 오공의 궁극기 띄우기에 맞춰 정글러가 들어오는 개입이 위험하니 강가 시야를 잘 잡으세요.', item: '갈라진 하늘을 첫 코어로 가서 체력을 높이고 타격 시 회복으로 버티세요. 신발은 오공의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'바위 피부\'의 체력 재생 효과를 점화로 억제하고 킬각을 잡으세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'로 원거리에서 견제하며 체력을 회복해요. (Q)\'이중 저주\'가 돌아오는 경로를 확인하며 옆으로 움직여 피해를 최소화하세요. 미니언을 이용해 거리를 좁히며 스칼의 체력을 관리하는 것이 중요해요.', lv3: '오로라가 (E)\'마법의 문\'으로 둔화를 걸고 뒤로 도약하면 무리하게 쫓지 마세요. (W)\'장막 너머로\'로 투명해진 오로라를 쫓기보다는 스킬을 아껴두는 것이 좋아요. (E)\'이랴!\'로 거리를 좁힌 뒤 (Q)\'덫날리기\'를 맞춰 오로라를 끌어당기며 싸우세요.', lv6: '오로라가 (R)\'세계의 경계\'로 영역을 만들면 그 안에서 이동할 때 둔화가 걸릴 수 있으니 조심하세요. 오로라의 (W)\'장막 너머로\'가 사용된 것을 확인한 뒤 (R)\'돌겨어어억!!!\'으로 돌진하여 압박하세요. 스칼의 체력을 잘 살피며 정글러와 함께 오로라를 몰아붙여 보세요.', item: '첫 코어로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 오로라의 마법 피해와 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도를 활용해 오로라의 (E)\'마법의 문\'을 통한 거리 벌리기를 차단하세요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\' 덕분에 기본 방어력과 마법 저항력이 높고 (Q)\'용암 균열\'로 견제해요. 균열 방향을 보고 옆으로 피하되, 끝에 생기는 용암 기둥을 등지고 서면 (E)\'화염 돌진\'에 띄워질 수 있으니 조심하세요. (E)\'이랴!\'를 활용해 거리 조절을 하며 스칼의 체력을 보존하는 것이 중요해요.', lv3: '(E)\'화염 돌진\'이 벽에 부딪히면 띄우니 벽 근처에서는 싸우지 마세요. (W)\'불꽃 풀무질\'의 마지막 불꽃에 맞으면 불안정 상태가 되니 정면에서 맞지 않게 조심하세요. (Q)\'덫날리기\'로 적을 붙잡은 뒤 (W)\'버럭버럭\'의 빠른 공격으로 피해를 입히세요.', lv6: '(R)\'대장장이 신의 부름\'의 정령 방향을 확인하고 재시전 돌진에 맞지 않게 피하세요. (R)\'돌겨어어억!!!\'으로 진입할 때 보호막을 활용해 (W)\'불꽃 풀무질\'의 피해를 상쇄하며 싸우세요. 오른은 라인에서 아이템을 제작해 버티므로 무리하게 킬을 노리기보다 라인 관리에 집중하세요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력을 모두 챙겨 맞서세요. 신발은 강인함과 마법 저항력을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 오른은 체력이 많아 처치가 어려우니 순간이동으로 라인 복귀를 빠르게 하세요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'를 던져 방어력을 낮추고 둔화를 걸면 거리를 벌리세요. (E)\'이랴!\'를 사용하여 짧게 진입해 피해를 주고 빠르게 빠지는 방식으로 대응해요. 스칼의 용기가 충분할 때만 싸우고 초반부터 무리하게 붙지는 마세요.', lv3: '올라프가 (W)\'버티기\'를 사용하여 보호막을 얻었을 때는 (W)\'버럭버럭\'의 공격 속도 증가를 아끼며 기다리세요. (Q)\'덫날리기\'로 적을 끌어당기려 할 때 올라프의 (E)\'무모한 강타\'가 들어오면 위험하니 주의해야 해요. 올라프의 (Q)\'역류\' 도끼를 주우러 가는 타이밍에 맞춰 (E)\'이랴!\'로 거리를 조절하며 싸우세요.', lv6: '올라프가 (R)\'라그나로크\'를 사용하면 이동 방해 효과에 면역이 되니 (R)\'돌겨어어억!!!\'의 밀어내기 효과가 통하지 않음을 기억하세요. 궁극기 사용 시점에는 정면 대결을 피하고 (R)\'라그나로크\' 지속 시간이 끝날 때까지 기다리며 라인을 관리해요. 체력이 낮은 올라프가 (P)\'광전사의 분노\'로 회복하며 버티지 못하도록 조심해야 해요.', item: '첫 코어는 거대한 히드라로 가서 체력 기반 광역 피해로 라인을 빠르게 밀고 교전 피해를 높이세요. 올라프의 물리 피해를 줄이기 위해 판금 장화를 먼저 올리세요.', spell: '점멸과 점화를 추천해요. 올라프가 (P)\'광전사의 분노\'로 얻는 생명력 흡수를 점화의 치유 감소 효과로 억제하며 싸우세요.' },
    '요네': { lv1: '요네가 (Q)\'필멸의 검\' 중첩을 쌓아 돌풍으로 띄우려 하면 거리를 조절하세요. (E)\'이랴!\'를 사용하여 빠르게 접근한 뒤 짧게 평타를 치고 빠지는 방식으로 교환을 최소화하세요. 요네가 돌풍을 사용하기 전까지는 체력 관리에 집중하며 첫 웨이브를 받아내세요.', lv3: '(E)\'영혼해방\'을 사용한 요네가 다시 육신으로 돌아오는 타이밍에 맞춰 (Q)\'덫날리기\'로 붙잡으세요. 요네의 (W)\'영혼 가르기\' 보호막이 생성된 동안에는 (W)\'버럭버럭\'의 추가 피해를 아꼈다가 보호막이 사라진 뒤에 넣으세요. 요네의 (Q)\'필멸의 검\' 중첩이 쌓였을 때는 무리하게 진입하지 말고 주의하세요.', lv6: '(R)\'운명봉인\'은 경로의 적을 끌어당기니 팀원과 일직선으로 서 있지 않도록 주의하세요. 요네가 (E)\'영혼해방\'으로 진입할 때 (R)\'돌겨어어억!!!\'을 사용하여 보호막으로 피해를 흡수하고 요네를 밀어내세요. 요네의 (R)\'운명봉인\'이 빠진 뒤에는 (E)\'이랴!\'와 (Q)\'덫날리기\'로 거리를 좁히며 킬각을 잡으세요.', item: '첫 코어 아이템으로 삼위일체를 선택해 전투 지속력을 높이세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요네의 (W)\'영혼 가르기\' 보호막이 사라진 뒤 점화로 피해를 더해 마무리하세요.' },
    '요릭': { lv1: '요릭이 (Q)\'최후의 의식\'으로 미니언을 쳐서 무덤을 만들 때 (Q)\'덫날리기\'로 끌어당겨 흐름을 끊으세요. (P)\'영혼의 길잡이\' 망령들이 달라붙으면 스칼의 체력이 빠르게 닳으니 짧게 딜교환하고 빠지세요. 초반 웨이브부터 강하게 압박하며 스칼의 용기를 유지하세요.', lv3: '(E)\'애도의 안개\'를 맞으면 둔화되고 망령들이 몰려오니 즉시 (E)\'이랴!\'로 거리를 벌리거나 요릭 본체에 붙으세요. (W)\'망자의 진\' 벽에 갇히면 평타로 빠르게 부수며 (W)\'버럭버럭\'으로 요릭을 강하게 타격하세요. 요릭의 (Q)\'최후의 의식\'이 빠진 타이밍에 공격적으로 들어가서 체력을 깎으세요.', lv6: '(R)\'군도의 장송곡\'으로 마녀가 나오면 지속 싸움이 힘들어지니 (R)\'돌겨어어억!!!\'의 보호막을 믿고 빠르게 진입해 요릭을 먼저 처치하세요. 마녀가 라인을 밀어붙이면 포탑 근처에서 (Q)\'덫날리기\'로 요릭을 끌어와 정글러와 함께 잡으세요. 스칼에서 내렸을 때 마녀와 망령의 집중 공격을 받지 않도록 주의하며 용기를 회복하세요.', item: '판금 장화는 요릭과 망령의 기본 공격 피해를 줄여줘요. 갈라진 하늘을 가서 체력을 높이고 타격 시 체력 회복으로 유지력을 챙기세요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'최후의 의식\'의 회복량을 줄여야 킬각을 잡기 편해요.' },
    '우디르': { lv1: '우디르는 (Q)\'야생 발톱\' 태세의 공격이 매우 강력하니 1~2레벨에는 맞대결을 피하세요. (Q)\'덫날리기\'로 멀리서 우디르의 체력을 깎으며 거리 조절을 하는 것이 좋아요. 스칼의 용기를 잘 관리하며 라인을 받아내세요.', lv3: '우디르가 (E)\'불길 쇄도\'를 사용해 기절을 노리면 (E)\'이랴!\'로 대응하며 거리를 조절하세요. (W)\'강철 갑옷\'이 켜져 있을 때는 우디르의 회복이 강하니 딜교환을 멈추고 기다려요. 우디르의 스킬이 빠진 뒤 (E)\'이랴!\'로 진입해 (W)\'버럭버럭\'의 빠른 공격을 넣으세요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\'을 켜고 쫓아오면 (R)\'돌겨어어억!!!\'의 보호막으로 피해를 버티세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 효과에 면역이 되면 (Q)\'덫날리기\'를 아끼세요. 우디르의 폭풍이 끝난 뒤 (E)\'이랴!\'로 진입해 승부를 보세요.', item: '삼위일체를 첫 코어로 올려 전투 지속력을 높이세요. 신발은 우디르의 마법 피해와 기절을 견디기 위해 헤르메스의 발걸음을 선택해요.', spell: '점멸과 점화를 추천해요. 점화로 우디르의 (W)\'강철 갑옷\'에 의한 체력 회복을 억제하며 마무리하세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 거리를 벌리며 둔화를 걸고 견제하니 미니언 사이에서 거리를 유지하세요. (E)\'이랴!\'를 사용해 빠르게 접근하거나 스칼의 용기를 채우는 것에 집중하며 무리하게 딜교하지 마세요. (Q)\'부식성 폭약\'이 빠진 직후에 진입하면 우르곳의 견제를 줄일 수 있어요.', lv3: '우르곳의 (E)\'경멸\'은 돌진하며 적을 뒤로 던지고 기절시키니 돌진 경로를 보고 미리 피하거나 (E)\'이랴!\'로 반응하세요. (W)\'심판의 원\'이 켜진 동안에는 우르곳의 화력이 매우 강하니 (Q)\'덫날리기\'로 끌어당겨 거리를 좁힌 뒤 (W)\'버럭버럭\'을 활용해 짧게 교환하고 빠지세요. (E)\'경멸\'이 빠진 시점이 딜교환을 시도하기 가장 좋은 타이밍이에요.', lv6: '우르곳의 (R)\'불사의 공포\' 섬광탄을 맞았다면 체력이 처형 기준 밑으로 떨어지면 제압당해 끌려가니 즉시 교전을 끊고 체력을 지키세요. (R)\'돌겨어어억!!!\'을 사용해 보호막을 얻고 우르곳의 진입을 차단하며 싸우는 것이 중요해요. 스칼이 없는 상태에서 우르곳의 (E)\'경멸\'과 (R)\'불사의 공포\' 연계에 노출되지 않도록 라인 관리에 신경 쓰며 정글러를 부르세요.', item: '판금 장화와 굶주린 히드라를 추천해요. 판금 장화로 우르곳의 기본 공격 피해를 줄이고 굶주린 히드라로 교환 시 유지력을 높이세요.', spell: '점멸과 점화를 추천해요. 우르곳의 체력이 낮아졌을 때 점화로 마무리 피해를 더해 확실하게 처치하세요.' },
    '워윅': { lv1: '워윅은 (Q)\'야수의 송곳니\'로 도약해 체력을 회복하며 강하게 압박하니 1~2레벨에는 거리를 조절하며 (Q)\'덫날리기\'로 견제하세요. 워윅이 (Q)\'야수의 송곳니\'를 사용해 들어올 때 (E)\'이랴!\'로 거리를 벌리거나 맞받아치며 스칼의 용기를 관리해야 해요. 워윅의 체력이 낮아지면 (P)\'끝없는 허기\'로 인해 회복력이 매우 높아지니 주의하세요.', lv3: '워윅의 (E)\'원시의 포효\'가 켜져 있는 동안은 받는 피해가 줄어드니 그 지속시간 동안은 딜을 아끼는 게 좋아요. 워윅의 (E)\'원시의 포효\'가 끝나고 공포가 발동하기 전에 (E)\'이랴!\'로 빠르게 진입하거나 빠져나오며 딜교환을 하세요. 워윅이 (Q)\'야수의 송곳니\'로 물었을 때 (Q)\'덫날리기\'를 적중시켜 끌어당기며 싸우면 도움이 돼요.', lv6: '워윅의 (R)\'무한의 구속\'은 대상을 제압하므로 제압 중에는 점멸이나 스킬을 쓸 수 없으니 주의하세요. (R)\'돌겨어어억!!!\'의 보호막을 활용해 워윅의 공격을 버티며 싸우되, 워윅이 제압을 시도할 때는 정면에서 비켜서세요. 워윅의 체력이 낮을 때 (P)\'끝없는 허기\' 효과가 강해지니 정글러를 불러 함께 마무리하는 것이 좋아요.', item: '첫 코어 아이템으로 굶주린 히드라를 올리고 신발은 판금 장화로 선택하세요. 굶주린 히드라로 공격력을 높이고 판금 장화로 워윅의 기본 공격 피해를 줄이는 것이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 체력 회복 효과를 줄여야 킬각을 잡기 편해요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 빠르게 접근하며 체력을 회복해요. 1~2레벨에는 미니언 사이의 거리를 조절하며 이렐리아의 (Q)\'칼날 쇄도\'가 닿지 않게 주의하세요. 이렐리아가 들어오면 (Q)\'덫날리기\'를 맞혀 붙잡아 흐름을 끊고, 빗나갔다면 무리하지 말고 물러나세요.', lv3: '이렐리아의 (E)\'쌍검협무\'가 두 칼날을 던져 기절을 시키려 할 때 칼날이 모이는 경로를 피하세요. 이렐리아가 (W)\'저항의 춤\'을 사용하여 받는 피해를 줄이고 있을 때는 (W)\'버럭버럭\'을 낭비하지 말고 충전이 끝난 뒤에 교환하세요. (E)\'이랴!\'로 거리를 좁히거나 벌리며 이렐리아의 (Q)\'칼날 쇄도\' 스킬을 빼는 것이 중요해요.', lv6: '이렐리아가 (R)\'선봉진격검\'을 사용해 결계를 만들고 둔화를 걸면 무리하게 쫓아가지 마세요. 스칼의 체력이 낮아질 때 (R)\'돌겨어어억!!!\'을 사용해 보호막을 얻고 이렐리아를 밀어내며 탈출하거나 역습을 노려요. 이렐리아가 (Q)\'칼날 쇄도\'로 미니언을 타고 들어오는 경로를 미리 파악해 정글러와 함께 압박하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 이렐리아의 기본 공격 피해를 줄여주고, 갈라진 하늘은 교전 중 타격을 입히기에 좋아요.', spell: '점멸과 점화. 점화로 이렐리아의 (Q)\'칼날 쇄도\'를 통한 체력 회복 효과를 줄여서 킬을 노리세요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 지형 근처에서 촉수 공격을 하니 벽에서 멀리 떨어져 싸우세요. (Q)\'촉수 강타\'의 범위를 피해 거리를 조절하다가 (E)\'이랴!\'로 빠르게 진입해 짧은 딜교환을 하고 빠지세요.', lv3: '(E)\'영혼의 시험\'에 맞으면 내 영혼이 분리되고, 일라오이가 영혼을 때리면 피해 일부가 나에게 들어오니 영혼 근처에서 오래 맞붙지 마세요. 영혼에서 너무 멀어지면 내가 숙주가 되어 촉수가 따라붙으니 거리를 조절하세요. (E)\'영혼의 시험\'이 빠진 타이밍에 (Q)\'덫날리기\'로 끌어당기고 (W)\'버럭버럭\'의 네 번째 공격까지 빠르게 적중시키세요.', lv6: '(R)\'믿음의 도약\'이 사용되면 주변에 촉수가 많이 생겨 위험하니, 보호막을 얻는 (R)\'돌겨어어억!!!\'으로 진입한 뒤 빠르게 승부를 보세요. 일라오이가 촉수를 많이 소환한 상태에서는 정글러를 불러 함께 공격하는 것이 좋아요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체의 공격 속도와 체력으로 지속 싸움을 이어가고, 판금 장화로 일라오이의 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀를 빠르게 하고, 점멸로 일라오이의 (E)\'영혼의 시험\' 사거리에서 벗어나거나 추격하세요.' },
    '자크': { lv1: '자크가 (Q)\'탄성 주먹\'으로 끌어당기려 하면 (E)\'이랴!\'의 돌진을 활용해 거리를 조절하세요. 1~2레벨에는 스칼을 타고 (W)\'버럭버럭\'의 공격 속도 증가를 이용해 짧게 교환하며 압박하세요. 자크가 (P)\'세포 분열\' 조각을 쉽게 줍지 못하도록 거리를 유지하며 체력 차이를 벌려야 해요.', lv3: '자크가 (E)\'새총 발사\'를 충전하며 돌진을 준비하면 (E)\'이랴!\'로 빠르게 반응하여 위치를 잡으세요. (Q)\'탄성 주먹\'에 붙잡히면 둔화가 걸리니 (Q)\'덫날리기\'로 먼저 자크를 끌어당겨 보세요. (W)\'버럭버럭\'의 네 번째 공격까지 맞힌 뒤에 빠져서 자크가 (W)\'불안정 물질\'을 쓰기 어렵게 만드세요.', lv6: '자크가 (R)\'바운스!\'로 튀어 오르며 적을 띄우려 하면 (R)\'돌겨어어억!!!\'을 사용하여 보호막을 얻고 맞서세요. 자크는 (P)\'세포 분열\'로 부활할 수 있으니 조각이 떨어지면 (E)\'이랴!\'로 조각 근처에 붙어 다시 합쳐지기 전에 처리하세요. 자크의 (E)\'새총 발사\'가 빠진 타이밍을 노려 라인을 밀고 정글러와 함께 압박하세요.', item: '자크의 마법 피해를 줄이는 헤르메스의 발걸음을 신으세요. 첫 코어 아이템으로는 전투 지속력을 높여주는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 자크가 (P)\'세포 분열\' 조각을 흡수해 체력을 회복하는 것을 억제하세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 체력을 회복하며 강하게 공격해요. 1~2레벨에는 (E)\'이랴!\'로 빠르게 접근해 짧게 딜교환하고 바로 빠지세요. (P)\'전쟁 단련\' 중첩이 쌓이면 자헨의 공격력이 올라가니 너무 오래 붙어 있지 마세요.', lv3: '자헨의 (W)\'공포의 귀환\'에 끌려가면 위험하니 직선 경로에서 벗어나세요. (E)\'찬란한 쇄도\'로 들어오는 자헨에게 (Q)\'덫날리기\'를 맞춰 거리를 조절하세요. (W)\'버럭버럭\'의 빠른 공격으로 피해를 입히고 자헨의 (Q)\'다르킨의 글레이브\' 재사용으로 인한 공중 띄우기를 피하며 움직이세요.', lv6: '(R)\'돌겨어어억!!!\'으로 진입해 보호막을 얻으며 자헨의 (R)\'단호한 판결\' 낙하 지점에서 벗어나세요. (P)\'전쟁 단련\' 효과로 자헨이 부활할 수 있으니 체력을 모두 깎았다고 방심하지 마세요. 정글러가 올 때 (Q)\'덫날리기\'로 상대를 붙잡아 빠르게 처리하세요.', item: '갈라진 하늘을 첫 코어로 가서 체력을 보충하고 강력한 첫 타격 피해를 입히세요. 신발은 자헨의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨은 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하므로 점화의 치유 감소가 효과적이에요.' },
    '잭스': { lv1: '1~2레벨에는 잭스가 (Q)\'도약 공격\'으로 순식간에 접근하여 (P)\'가차없는 맹공\'으로 공격 속도를 높이며 싸우려 하니 정면 대결을 피하세요. (Q)\'덫날리기\'로 잭스의 접근을 방해하거나 거리를 조절하며 짧게 교전하세요. 스칼의 용기가 낮아지면 무리하게 맞붙지 말고 거리를 벌리며 용기를 회복해야 해요.', lv3: '잭스가 (E)\'반격\'을 사용하여 기본 공격을 회피하고 기절을 시도하면 (W)\'버럭버럭\'을 사용한 평타 교환을 멈추고 뒤로 물러나세요. 잭스의 (E)\'반격\'이 끝난 직후에 (Q)\'덫날리기\'로 잭스를 끌어당기며 (E)\'이랴!\'를 사용해 진입하면 효과적으로 딜교환을 할 수 있어요. 잭스의 (Q)\'도약 공격\'이 빠진 타이밍에 (E)\'이랴!\'로 거리를 좁히는 것이 좋아요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용하면 방어력과 마법 저항력이 올라가니 그동안은 정면 승부를 피하세요. (E)\'반격\'이 빠진 것을 확인한 뒤 (R)\'돌겨어어억!!!\'으로 보호막을 두르고 진입해 스칼의 돌격 피해를 입히며 킬각을 노려보세요. 스칼에서 내렸을 때는 (Q)\'덫날리기\'가 바뀐 원거리 공격으로 뒤로 물러나며 용기를 회복하세요.', item: '첫 코어는 거대한 히드라로 가서 체력 기반 광역 피해로 라인을 빠르게 밀고 교전 피해를 높이세요. 잭스의 기본 공격 피해를 줄이기 위해 판금 장화를 먼저 구매하세요.', spell: '점멸과 점화를 추천해요. 점멸을 사용해 잭스의 (E)\'반격\' 범위를 피하거나 (Q)\'도약 공격\'을 흘리고, 점화로 적의 체력을 깎아 킬을 완성하세요.' },
    '제이스': { lv1: '제이스는 캐논 형태에서 (Q)\'전격 폭발\'로 멀리서 견제하며 압박해요. (Q)\'전격 폭발\'의 직선 경로를 피하며 미니언 뒤에 숨어 체력을 보존하세요. 제이스가 막타를 치기 위해 다가오는 순간에 (E)\'이랴!\'로 빠르게 진입해 체력을 깎으세요.', lv3: '해머 형태의 (E)\'천둥 강타\'에 밀려나면 딜교환이 끊기니, 상대가 스킬을 쓴 이후에 (Q)\'덫날리기\'로 적을 끌어당기세요. 캐논 형태의 (E)\'가속 관문\'을 통과한 (Q)\'전격 폭발\'은 피해가 크니 관문이 열리면 즉시 옆으로 피하세요. (E)\'천둥 강타\'가 빠진 틈을 타 (W)\'버럭버럭\'의 네 번째 공격까지 모두 적중시키세요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 활용해 원거리에서 빠르게 진입하며 제이스를 당황시키세요. 제이스가 (R)\'머큐리 캐논\'으로 바꿔 첫 공격으로 방어력을 깎기 전에 (E)\'이랴!\'로 거리를 좁혀야 해요. (E)\'천둥 강타\'가 빠진 것을 확인하고 진입하면 제이스가 도망치기 어려워 킬각을 잡기 편해요.', item: '삼위일체를 첫 코어로 가서 공격 속도와 체력을 챙기고 강력한 피해를 입히세요. 신발은 제이스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (Q)\'덫날리기\'와 점화를 함께 사용해 제이스의 체력을 순식간에 깎아 킬각을 잡으세요.' },
    '초가스': { lv1: '초가스가 (Q)\'파열\'을 사용해 적을 공중에 띄우면 스킬을 쓸 수 없으니, 바닥의 원형 표시를 보고 빠르게 피하세요. (E)\'날카로운 가시\'의 둔화가 걸리면 움직임이 느려지니 (E)\'이랴!\'로 빠르게 접근하거나 거리를 조절하며 스칼의 용기를 쌓으세요. (P)\'육식\'으로 미니언을 먹으며 체력을 회복하는 초가스를 계속 압박하며 딜교환을 유도하세요.', lv3: '(W)\'흉포한 울부짖음\'은 침묵이라 맞은 뒤에는 스킬을 쓸 수 없으니, 맞기 전에 (Q)\'덫날리기\'를 미리 던져 붙잡으세요. (Q)\'파열\'을 피한 뒤 (E)\'이랴!\'로 진입해 (W)\'버럭버럭\'의 네 번째 공격까지 빠르게 넣고 빠지세요. 초가스의 침묵 스킬이 빠진 타이밍을 노려 (Q)\'덫날리기\'로 끌어당기면 계속해서 압박할 수 있어요.', lv6: '(R)\'포식\'은 방어력을 무시하는 큰 고정 피해를 주니, 체력이 낮을 때 초가스와 가까이 있지 마세요. (R)\'돌겨어어억!!!\'의 보호막으로 (Q)\'파열\' 피해를 흡수하며 진입해 초가스를 뒤로 밀어내며 진형을 흔드세요. 초가스가 (R)\'포식\'을 미니언에 사용해 성장을 시도했다면, 그 즉시 공격적으로 들어가 킬각을 잡으세요.', item: '체력이 많은 초가스에게 현재 체력 비례 피해가 들어가는 몰락한 왕의 검을 첫 코어로 가세요. 신발은 (W)\'흉포한 울부짖음\'의 침묵 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 초가스의 (P)\'육식\' 회복 효과를 감소시키세요.' },
    '카밀': { lv1: '카밀은 (P)\'적응형 방어 체계\'로 평타 시 보호막을 얻고 (Q)\'정확성 프로토콜\'로 강화 평타를 쳐요. (Q)\'정확성 프로토콜\'의 두 번째 강화 타격은 매우 아프니 그 타이밍에는 거리를 벌려 피하세요. 1~2레벨에는 (W)\'버럭버럭\'을 활용해 짧게 딜교환하며 스칼의 체력을 보존하세요.', lv3: '(W)\'전술적 휩쓸기\'의 바깥쪽 절반에 맞으면 둔화되고 카밀이 회복하니 안쪽으로 파고들거나 완전히 벗어나세요. (E)\'갈고리 발사\'의 기절을 조심하고, 기절이 풀린 후 (E)\'이랴!\'로 빠르게 접근해 (W)\'버럭버럭\'의 네 번째 공격을 적중시키세요. 카밀의 (E)\'갈고리 발사\'가 빠진 틈을 타 (Q)\'덫날리기\'로 붙잡아 끌어당기며 딜교환하세요.', lv6: '(R)\'마법공학 최후통첩\'은 어떤 방법으로도 빠져나갈 수 없게 가두니, 갇혔다면 도망치려 하지 말고 (Q)\'덫날리기\'와 (W)\'버럭버럭\'으로 맞서세요. 카밀이 궁극기를 쓴 뒤에는 (R)\'돌겨어어억!!!\'으로 보호막을 두르고 진입해 역습하세요. 라인 주변 벽이 많은 곳에서는 (E)\'갈고리 발사\'를 이용한 기습적인 정글 개입을 항상 주의하세요.', item: '삼위일체를 첫 코어로 선택해 공격 속도와 체력을 높여 맞딜 능력을 강화하세요. 신발은 카밀의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 카밀이 (W)\'전술적 휩쓸기\'로 체력을 회복하는 것을 점화의 치유 감소로 억제하세요.' },
    '카사딘': { lv1: '1~2레벨 구간에는 (Q)\'덫날리기\'를 사용하여 카사딘에게 접근하며 압박을 시도하세요. 카사딘이 (Q)\'무의 구체\'를 통해 보호막을 얻는 것을 확인하며 무리한 진입은 피해요. (E)\'이랴!\'로 이동 속도를 얻으며 스칼의 용기를 관리하는 것이 중요해요.', lv3: '3레벨 이후에는 카사딘의 (E)\'힘의 파동\'이 빠진 것을 확인하고 진입해야 해요. 상대의 둔화가 없다면 (E)\'이랴!\'로 달려가 (W)\'버럭버럭\'의 강력한 추가 피해를 입히세요. (Q)\'덫날리기\'로 적을 끌어당기며 지속적인 공격을 이어가는 것이 좋아요.', lv6: '6레벨 이후에는 카사딘이 (R)\'균열 이동\'을 사용해 거리를 벌리려 할 때 (R)\'돌겨어어억!!!\'로 즉시 추격하세요. 전투 중에 스칼의 용기를 유지하며 보호막을 얻는 것에 집중해야 해요. 라인을 강하게 밀어 넣으며 정글러의 도움을 받는 것이 좋아요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 카사딘의 마법 피해를 견디기 위해 헤르메스의 발걸음을 가고, 전투 지속력을 위해 갈라진 하늘을 선택해요.', spell: '점멸과 점화를 추천해요. 점멸로 (R)\'균열 이동\'으로 빠지는 카사딘과의 거리를 다시 좁히고, 점화로 마무리 피해를 더해 킬각을 잡으세요.' },
    '카시오페아': { lv1: '시작부터 (Q)\'맹독 폭발\' 견제가 심하므로 스칼의 체력으로 버티며 거리를 조절하세요. 무리하게 진입하기보다 (E)\'이랴!\'를 활용해 짧게 딜교환을 하고 빠지는 식으로 체력 압박을 줘요.', lv3: '(W)\'독기의 늪\' 위에 있으면 (E)\'이랴!\'를 사용할 수 없으니 상대의 늪 설치 여부를 먼저 확인하세요. (W)\'독기의 늪\'이 빠진 것을 확인한 뒤 (E)\'이랴!\'로 진입해 (W)\'버럭버럭\'의 마지막 공격까지 빠르게 적중시켜야 해요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 믿고 진입하되 (R)\'석화의 응시\'를 사용할 때 빠르게 등을 돌려 기절을 피하세요. 기절을 피하면 둔화만 걸리므로 계속 추격해 킬각을 잡고 정글러의 개입을 유도해요.', item: '헤르메스의 발걸음과 삼위일체로 가세요. 마법 저항력과 강인함으로 군중 제어 시간을 줄이고 공격 속도와 체력을 보강해 지속 전투력을 높여요.', spell: '점멸과 점화예요. (E)\'쌍독니\'의 체력 회복 효과를 억제하고 확실한 킬각을 잡기 위해 선택해요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 날려 (P)\'폭풍의 표식\'을 쌓으려 해요. (P)\'겁쟁이 도마뱀 스칼\'이 피해를 대신 입어주니 (E)\'이랴!\'로 빠르게 접근해 압박하세요. 표식이 세 번 쌓이면 기절하므로 맞은 횟수를 확인하며 거리 조절을 하세요.', lv3: '케넨이 (E)\'번개 질주\'로 거리를 벌리며 표식을 남기니, (Q)\'덫날리기\'를 맞춰 끌어당기세요. (W)\'전류 방출\'이 사용된 뒤에 (W)\'버럭버럭\'의 빠른 공격을 넣으면 짧은 시간 내에 큰 피해를 줄 수 있어요. 기절이 걸리기 전까지 최대한 빠르게 딜교환을 마치고 빠지세요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 사용하면 주변에 기절을 빠르게 쌓으니 무리하게 붙지 마세요. (R)\'돌겨어어억!!!\'의 보호막으로 피해를 버티며 진입해 케넨을 밀어내고 빠르게 처치하세요. 정글러가 함께 진입할 때 케넨의 기절에 걸려 스킬을 못 쓰지 않도록 주의하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력을 높이고 체력 회복으로 견제를 버티세요. 신발은 마법 저항력을 높이고 기절 지속시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. 케넨의 스킬로 인해 발생하는 기절을 정화로 즉시 풀고 공격을 이어가세요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'으로 성장하기 전까지는 초반 교전이 매우 약한 구간이에요. (Q)\'광휘의 일격\'에 맞으면 둔화와 방어력 감소가 걸리니, 직선 경로를 피하며 빠르게 다가가세요. 첫 웨이브부터 강하게 압박해 케일이 편하게 파밍하지 못하도록 하세요.', lv3: '(E)\'이랴!\'로 빠르게 접근한 뒤 (Q)\'덫날리기\'로 붙잡아 끌어당기며 피해를 입히세요. 케일이 (W)\'천상의 축복\'으로 체력을 회복하고 도망치려 하면 (W)\'버럭버럭\'의 빠른 공격으로 계속 추격하세요. 상대의 (E)\'화염주문검\'은 잃은 체력에 비례해 강해지니 내 체력이 낮을 때는 무리한 교전을 피하세요.', lv6: '(R)\'돌겨어어억!!!\'으로 진입하면 보호막 덕분에 (Q)\'광휘의 일격\' 견제를 버티며 빠르게 붙을 수 있어요. 다만 케일이 (R)\'신성한 심판\'으로 자신을 무적으로 만들면 모든 공격이 막히니, 무적이 끝나는 타이밍을 노려 공격하세요. 라인을 밀어 넣고 정글러를 불러 케일이 무적 스킬을 쓰기 전에 빠르게 제압하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기고 교전 유지력을 높이세요. 신발은 케일의 마법 피해를 줄이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (W)\'천상의 축복\'의 회복량을 줄여 확실하게 처치하세요.' },
    '코그모': { lv1: '코그모가 (Q)\'부식성 침\'으로 계속 견제해요. 미니언 뒤에 숨어서 피해를 최소화하며 (P)\'겁쟁이 도마뱀 스칼\'의 체력을 보존하세요. 무작정 들어가기보다 상대의 스킬 쿨타임을 확인하며 거리를 조절해요.', lv3: '(E)\'공허의 분비물\'이 깔리면 둔화 때문에 접근이 어려워요. (E)\'이랴!\'로 빠르게 진입한 뒤 (Q)\'덫날리기\'를 맞춰 상대를 붙잡으세요. (W)\'버럭버럭\'의 빠른 공격으로 짧은 딜교환을 마치고 빠져나오세요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 이용해 코그모의 (R)\'살아있는 곡사포\' 피해를 버티며 진입하세요. 진입 후에는 (W)\'버럭버럭\'과 일반 공격으로 빠르게 체력을 깎아 킬각을 잡으세요. 정글러가 올 때까지 라인을 당기며 기회를 엿보세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 상대의 강력한 마법 피해를 견디고 (E)\'공허의 분비물\' 둔화 시간을 줄여야 해요.', spell: '점멸과 점화를 추천해요. 부족한 접근 거리를 보완하고 체력이 낮은 코그모를 확실하게 마무리하기 위해서예요.' },
    '코르키': { lv1: '(Q)\'인광탄\' 견제가 심하므로 스칼의 체력을 이용해 최대한 버티며 파밍하세요. (E)\'이랴!\'로 진입하려 하면 상대가 뒤로 빠지니 미니언 뒤에서 거리를 좁히며 기회를 보세요.', lv3: '(W)\'발키리\'가 빠진 순간을 노려 (E)\'이랴!\'로 빠르게 진입하세요. (Q)\'덫날리기\'를 맞춰 상대를 끌어당긴 뒤 (W)\'버럭버럭\'의 네 번째 공격까지 빠르게 적중시키는 것이 중요해요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 믿고 과감하게 진입하여 (R)\'미사일 폭격\'을 강제로 빼게 만드세요. 상대가 (W)\'발키리\'로 도망가더라도 (Q)\'덫날리기\'로 끝까지 추격해 킬각을 잡으세요.', item: '갈라진 하늘과 헤르메스의 발걸음을 추천해요. 갈라진 하늘의 체력과 회복으로 견제를 버티고 헤르메스의 발걸음으로 (Q)\'인광탄\'의 마법 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 원거리 챔피언의 견제로 인해 라인 복귀가 중요하며 점멸을 통한 기습 진입이 필요해요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식을 남겨 원거리에서 견제하며 (Q)\'실명 공격\'으로 시야를 좁혀요. (E)\'이랴!\'를 사용하여 빠르게 접근하되, (P)\'매사냥\' 표식이 붙었을 때는 무리하게 붙지 말고 스칼의 체력을 관리하세요. 스칼에서 내렸다면 (Q)\'덫날리기\'가 바뀐 원거리 공격으로 견제하며 스칼의 용기를 회복하세요.', lv3: '퀸이 (E)\'공중제비\'로 돌진했다가 뒤로 물러나며 거리를 벌리니, 물러난 직후의 빈틈에 (Q)\'덫날리기\'를 맞혀 끌어당기세요. (W)\'버럭버럭\'의 빠른 공격으로 퀸에게 붙어 네 번째 공격을 적중시키면 강력한 피해를 줄 수 있어요. (W)\'예리한 감각\'으로 빨라진 퀸을 쫓을 때는 (E)\'이랴!\'의 재사용 돌진까지 모두 활용하세요.', lv6: '퀸이 (R)\'후방 지원\'으로 빠르게 날아다니며 라인을 비우면 포탑을 압박하고 정글러와 합류하세요. (E)\'공중제비\'가 빠진 상태에서 (R)\'돌겨어어억!!!\'으로 보호막을 두르고 붙은 뒤, 스칼에 밀려난 퀸을 (Q)\'덫날리기\'로 다시 끌어당겨 킬각을 잡으세요.', item: '삼위일체를 첫 코어로 가서 공격 속도와 체력을 챙겨 끈질기게 추격하세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 퀸의 기동력에 대응해 라인 복귀를 빠르게 하고 로밍에 대처하세요.' },
    '크산테': { lv1: '크산테가 (Q)\'엔토포 타격\'으로 둔화를 걸며 중첩을 쌓아 끌어당기려 하니 거리 조절에 신경 쓰세요. (E)\'이랴!\'를 사용해 빠르게 접근하거나 빠지며 스칼의 체력을 관리하세요. 1~2레벨에는 크산테의 (Q)\'엔토포 타격\' 중첩이 쌓이기 전에 짧게 딜교환하고 물러나세요.', lv3: '(W)\'길을 여는 자\'는 저지 불가 돌진으로 기절을 거니, 충전 중일 때는 (E)\'이랴!\'로 경로를 피하세요. 크산테의 (E)\'발놀림\' 보호막이 사라진 뒤에 (W)\'버럭버럭\'의 빠른 평타를 몰아치세요. (Q)\'덫날리기\'로 적을 붙잡아 끌어당긴 뒤 짧은 딜교환을 마치고 안전하게 빠지세요.', lv6: '크산테가 (R)\'총공세\'를 사용해 방어력이 낮아진 상태가 되면 (R)\'돌겨어어억!!!\'으로 보호막을 얻으며 정면에서 맞서세요. 상대가 (R)\'총공세\'로 벽 너머로 밀어낼 때 정글러의 개입이 있을 수 있으니 주변 시야를 꼭 확인하세요. (Q)\'덫날리기\'로 끌어당긴 뒤 (W)\'버럭버럭\'의 마지막 공격까지 빠르게 적중시켜 킬각을 잡으세요.', item: '삼위일체를 첫 코어로 선택해 공격력과 체력을 높이고 강한 충격을 주세요. 신발은 크산테의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 크산테와의 교전이 길어질 수 있으니 순간이동으로 라인 복귀와 운영에 집중하세요.' },
    '탐켄치': { lv1: '탐 켄치가 (Q)\'혀 채찍\'으로 (P)\'절대 미각\' 중첩을 쌓으려 할 때 미니언 뒤에 숨어서 피하세요. (P)\'절대 미각\' 중첩이 세 번 쌓인 상태에서 (Q)\'혀 채찍\'에 맞으면 기절하니 최대한 거리를 유지하며 (Q)\'덫날리기\'로 짧게 딜교환을 하세요.', lv3: '탐 켄치의 (W)\'심연 잠수\' 범위에 들어가지 않도록 주의하며 (E)\'이랴!\'로 진입하거나 빠르게 빠져나오세요. (Q)\'혀 채찍\'에 맞으면 둔화가 걸리니 (W)\'버럭버럭\'의 빠른 공격으로 (P)\'절대 미각\' 중첩이 쌓이기 전에 교환을 마치세요.', lv6: '탐 켄치는 (P)\'절대 미각\' 중첩이 세 번 쌓인 나를 (R)\'집어삼키기\'로 삼킬 수 있으니, 중첩이 쌓이기 전에 (R)\'돌겨어어억!!!\'으로 보호막을 두르고 진입해 싸움을 거세요. (E)\'두꺼운 피부\'로 보호막을 만든 탐 켄치는 잘 버티니 보호막이 사라진 뒤 (W)\'버럭버럭\'의 네 번째 공격까지 넣어 마무리하세요.', item: '마법 피해가 주력인 탐 켄치를 상대하므로 헤르메스의 발걸음을 신발로 선택하세요. 첫 코어 아이템은 전투 지속력을 높여주는 굶주린 히드라를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 체력 회복 효과를 감소시키며 킬각을 잡으세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 훔치고 둔화를 걸어 1~2레벨 평타 싸움이 매우 강해요. (E)\'이랴!\'를 이용해 짧게 진입했다가 빠르게 빠지며 상대의 체력을 깎으세요. 트런들은 (P)\'헌납\'으로 유닛 처치 시 체력을 회복하니 미니언이 많이 죽는 타이밍에는 교전을 피하세요.', lv3: '트런들이 (W)\'얼음 왕국\'을 깔면 공격 속도와 이동 속도가 오르니 영역 밖으로 벗어나세요. (E)\'얼음 기둥\'에 가로막히면 (Q)\'덫날리기\'로 끌어당기기 어려우니 기둥이 빠진 것을 확인하고 진입하세요. (W)\'버럭버럭\'의 네 번째 공격을 맞히기 위해 (E)\'이랴!\'로 빠르게 붙어 피해를 입히세요.', lv6: '(R)\'돌겨어어억!!!\'의 보호막을 활용해 진입하되 (R)\'진압\'에 방어력과 체력을 뺏기면 순식간에 스칼에서 내릴 수 있으니 주의하세요. (R)\'진압\'의 효과가 끝난 뒤에 다시 (Q)\'덫날리기\'와 (E)\'이랴!\'를 섞어 공격하세요. 트런들이 (E)\'얼음 기둥\'으로 좁은 길목을 막으면 정글러의 갱킹에 노출되기 쉬우니 항상 퇴로를 확보하세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 체력을 챙기고 판금 장화의 효과로 트런들의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (P)\'헌납\'과 (W)\'얼음 왕국\'의 회복량을 낮춰 마무리하세요.' },
    '트린다미어': { lv1: '1~2레벨 구간에서는 트린다미어가 (P)\'격노\'로 치명타 확률을 높여 평타가 매우 강력하니 (P)\'겁쟁이 도마뱀 스칼\'의 체력을 아끼며 짧게 교전하세요. (Q)\'덫날리기\'를 맞히고 끌어당기기 전까지는 무리하게 붙지 말고 거리를 조절하는 것이 중요해요. 첫 웨이브는 최대한 체력을 보존하며 상대의 공격적인 진입을 받아내세요.', lv3: '트린다미어가 (E)\'회전 베기\'로 들어올 때 (E)\'이랴!\'로 맞부딪쳐 피해를 주고 빠르게 빠져나오세요. (W)\'조롱의 외침\'에 맞고 등을 돌리면 둔화되니, 맞더라도 정면을 유지하며 (W)\'버럭버럭\'의 빠른 공격으로 압박하세요. (Q)\'덫날리기\'로 적을 붙잡은 뒤 (E)\'이랴!\'를 다시 사용하여 돌진하면 강력한 피해를 입힐 수 있어요.', lv6: '(R)\'불사의 분노\'가 켜진 동안은 죽지 않으니 무리하게 공격하지 말고 (R)\'돌겨어어억!!!\'의 보호막으로 시간을 버티세요. 궁극기 지속 시간이 끝나는 순간이 가장 좋은 킬각이니 그때 모든 화력을 쏟아부으세요. 라인을 밀어 넣고 정글러를 부를 때는 상대의 (E)\'회전 베기\'가 빠진 타이밍을 노리는 것이 좋아요.', item: '갈라진 하늘을 첫 코어로 가서 공격력과 체력을 챙기고 체력 회복으로 버티세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 트린다미어의 (Q)\'피의 갈망\' 회복량을 줄여 확실하게 처치하세요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'와 (Q)\'실명 다트\'로 원거리에서 계속 괴롭혀요. 1~2레벨 구간에는 무리하게 맞붙기보다 미니언을 받아먹으며 체력을 관리하세요. (Q)\'덫날리기\'로 티모를 끌어당기려 하기 전에 (E)\'맹독 다트\'의 독 피해를 조심하며 거리를 조절해야 해요.', lv3: '(E)\'이랴!\'를 사용해 티모에게 돌진하여 거리를 좁히고 (Q)\'덫날리기\'를 맞춰야 해요. 티모가 (Q)\'실명 다트\'로 나를 실명시키면 그동안은 평타 교환을 미루고 실명이 풀린 뒤 (W)\'버럭버럭\'의 빠른 공격을 넣으세요. 티모가 (W)\'신속한 이동\'으로 도망가려 하면 (Q)\'덫날리기\'로 끌어당겨서 딜교환을 이어가세요.', lv6: '(R)\'돌겨어어억!!!\'으로 보호막을 두르고 티모에게 붙은 뒤, 스칼에 밀려난 티모를 (E)\'이랴!\'와 (Q)\'덫날리기\'로 다시 붙잡아 킬각을 잡으세요. 라인 곳곳에 깔린 (R)\'유독성 함정\' 버섯을 밟으면 이동 속도가 늦춰지니 맵을 잘 살피며 이동하세요. 티모가 버섯을 깔러 라인을 비우면 빠르게 포탑을 압박하여 이득을 챙겨야 해요.', item: '첫 코어 아이템으로 갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 (R)\'유독성 함정\'의 둔화를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 티모의 (W)\'신속한 이동\'을 따라잡고 체력이 낮은 티모를 확실하게 처치하기 위해 사용해요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'으로 멀리서 견제하며 초반에 강한 모습을 보여요. (E)\'이랴!\'를 사용하여 거리를 조절하며 스칼의 용기가 줄어들지 않게 주의하세요. 초반에는 무리한 교환보다 미니언을 챙기며 버티는 것이 좋아요.', lv3: '판테온이 (W)\'방호의 도약\'으로 기절을 시도하면 (E)\'이랴!\'를 사용하여 대응하세요. 판테온의 (E)\'방패 돌격\'이 켜진 동안은 정면 피해로부터 면역이니, 그 시간은 피하고 끝난 뒤에 (W)\'버럭버럭\'의 빠른 공격으로 딜교환을 시작하세요. 판테온의 강화된 스킬이 빠진 타이밍을 노려야 해요.', lv6: '판테온이 (R)\'거대 유성\'을 사용하여 다른 라인에 개입할 수 있으니 미니맵을 자주 확인하세요. (R)\'돌겨어어억!!!\'을 사용하여 보호막을 얻으며 판테온에게 진입해 킬각을 잡으세요. 스칼이 내린 상태에서 판테온의 스킬을 맞으면 위험하니 주의해야 해요.', item: '판금 장화와 굶주린 히드라를 추천해요. 판금 장화는 판테온의 기본 공격 피해를 줄여주고 굶주린 히드라는 전투 지속력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화로 판테온의 체력을 낮추어 킬을 노리거나 압박하세요.' },
    '피들스틱': { lv1: '1~2레벨에는 상대가 시야 밖에서 (Q)\'공포\'를 사용해 기습하지 못하도록 부시를 항상 조심하며 플레이하세요. (E)\'이랴!\'는 아껴 두었다가 기습을 받으면 곧바로 맞받아치는 데 쓰며 스칼의 용기를 유지하세요. 상대가 (W)\'풍작\'으로 체력을 회복하기 전에 거리를 조절하며 압박하세요.', lv3: '(E)\'수확\'의 범위 중심에 맞으면 침묵을 당해 (E)\'이랴!\'를 쓰지 못할 수 있으니 중심부를 피해서 진입하세요. (Q)\'덫날리기\'로 상대를 붙잡은 뒤 (W)\'버럭버럭\'의 강화 평타를 섞어 강력하게 딜교환을 시도하세요. 상대의 (Q)\'공포\'가 빠진 상태라면 (E)\'이랴!\'로 빠르게 파고들어 스칼을 다시 타는 것이 중요해요.', lv6: '(R)\'돌겨어어억!!!\'을 사용해 보호막을 얻으며 돌진하여 상대의 (R)\'까마귀 폭풍\' 피해를 버티며 싸우세요. 상대가 (R)\'까마귀 폭풍\'을 사용하기 위해 시야에서 사라진다면 즉시 뒤로 물러나거나 와드로 위치를 파악하세요. 라인을 빠르게 밀어 넣고 정글러를 호출하여 상대가 궁극기를 사용하기 어렵게 만드세요.', item: '헤르메스의 발걸음과 거대한 히드라를 추천해요. (Q)\'공포\'와 (E)\'수확\'의 제어 지속시간을 줄이고 공격력과 체력을 챙기기 위해서예요.', spell: '점멸과 정화를 추천해요. 점멸로 변수를 만들고 정화로 상대의 (Q)\'공포\'를 빠르게 풀어내어 역공을 준비하세요.' },
    '피오라': { lv1: '1~2레벨에는 피오라의 (Q)\'찌르기\' 돌진과 (P)\'치명적인 검무\'의 회복력을 조심해야 해요. (Q)\'덫날리기\'로 거리를 유지하며 피오라의 접근을 방해하고 스칼의 용기를 쌓는 것에 집중하세요. 피오라가 급소를 노리기 전에 (E)\'이랴!\'를 활용해 거리 조절을 하는 것이 좋아요.', lv3: '피오라의 (W)\'응수\'는 공격과 이동 불가 효과를 막고, 이동 불가 효과를 막아내면 찔린 적을 기절시키니 (W)\'응수\' 중에는 공격과 (Q)\'덫날리기\'를 멈추세요. (W)\'응수\'를 먼저 빼게 만든 뒤 (W)\'버럭버럭\'의 빠른 공격으로 적극적으로 딜교환을 시도하세요. 피오라의 (E)\'대가의 검술\' 둔화가 걸리면 무리하게 붙지 말고 거리를 벌려야 해요.', lv6: '피오라의 (R)\'대결투\'가 켜지면 피오라가 급소를 쉽게 찌르지 못하도록 (E)\'이랴!\'로 위치를 계속 바꾸며 움직이세요. (R)\'돌겨어어억!!!\'으로 돌진하며 보호막을 얻고 스칼의 돌격으로 피오라의 공격 흐름을 끊는 것이 중요해요. 피오라가 급소를 모두 가격하기 전에 정글러를 부르거나 라인을 밀어 압박하세요.', item: '삼위일체를 첫 코어로 가서 공격력과 스킬 가속을 챙기세요. 신발은 피오라의 기본 공격 피해를 줄이는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 피오라의 (P)\'치명적인 검무\'로 인한 체력 회복을 점화로 억제하며 킬각을 잡으세요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 깔아두고 라인 주도권을 가져가려 해요. 포탑 사거리 안에서 무리하게 교환하지 말고 미니언을 챙기며 (E)\'이랴!\'로 거리 조절을 하세요. 포탑이 설치되지 않은 틈을 노려 짧게 딜교환을 하는 것이 좋아요.', lv3: '하이머딩거의 (E)\'CH-2 전자폭풍 수류탄\'에 직격당하면 기절하니 수류탄이 떨어지는 위치를 잘 피하세요. 수류탄이 빠진 것을 확인했다면 (Q)\'덫날리기\'를 맞춰 하이머딩거를 끌어당기며 진입하세요. (W)\'버럭버럭\'의 빠른 공격으로 빠르게 몰아쳐야 포탑의 화력을 견딜 수 있어요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'를 사용해 포탑이나 수류탄을 강화하면 매우 위험하니 주의하세요. (R)\'돌겨어어억!!!\'로 보호막을 얻으며 진입해 하이머딩거를 밀어내고 스칼을 다시 타는 것이 중요해요. 포탑이 많은 곳에서 정면으로 맞서기보다 (E)\'이랴!\'로 빠르게 거리를 좁히며 라인을 밀어 넣으세요.', item: '삼위일체를 코어로 가고 신발은 헤르메스의 발걸음을 선택하세요. 하이머딩거의 마법 피해를 견디고 기절 지속시간을 낮추는 것이 중요해요.', spell: '점멸과 유체화를 추천해요. 유체화로 하이머딩거의 포탑 사거리를 빠르게 지나 본체에 도달하기 좋아요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_kled);
if (typeof module !== 'undefined') module.exports = top_kled;
